# -*- coding: utf-8 -*-
"""Аудит-цикл CDPM: обработчик ↔ аудитор (пакет работ АЦ-1 — контракты).

Автоматизация обмена, которым пилотная линия прошла 19 кругов вручную: аудитор
(независимая языковая модель) выдаёт пакет структурированных замечаний
по формализованному своду; обработчик отвечает на КАЖДОЕ (принято /
отклонено / частично — всегда с основанием-цитатой источника) и издаёт
новую версию свода; реестр находок ведёт жизненный цикл каждой находки;
метрика (Б, К, С) считается из реестра после каждого аудита.

Этот модуль — машинные формы и правила протокола (контракты раньше
конвейера, как в П-1): проверка замечаний, ответов, реестра, метрики,
правило diff-only и правило останова. Оркестратор живого цикла —
пакет АЦ-2.

Золотые правила, зашитые в контракт (оплачены ревизиями пилотной линии):

- замечание без адреса и доказательства-цитаты не существует;
- ни одно замечание не остаётся без ответа; принятие обязано цитировать
  источник так же, как отклонение (защита от уступчивости);
- находку закрывает только сторона, её открывшая: исправление
  подтверждает аудитор следующим обменом;
- diff-only: новая версия меняет только строки из принятых замечаний;
- регресс-токен: исправление закрытой находки обязано жить во всех
  последующих версиях;
- отклонено и повторено аудитором — тупик, решение владельца, не
  пинг-понг;
- останов: два независимых чистых аудита подряд, либо лимит обменов,
  либо стагнация метрики (лексикографическое сравнение (Б, К, С));
- успех судится терминальным реестром, а не метрикой раунда (A07,
  контракт П0 §1.2, 12.09.2026): живая блокирующая/критическая
  находка (перечень LIVE_STATES) даёт вердикт «не закрыто» — молчание
  аудитора закрытием не считается.
"""
from __future__ import annotations

import copy
import hashlib
import json
import os
import re
from pathlib import Path

from cdpm import model as _mdl
from cdpm import measure as _ms
from cdpm.diagnostics import summarize_items

SEVERITIES = ("БЛОКИРУЮЩЕЕ", "КРИТИЧЕСКОЕ", "СЕРЬЁЗНОЕ", "РЕДАКЦИОННОЕ")
DEFECT_CLASSES = ("искажение", "пропуск", "изобретение", "выбор чтения",
                  "потерянная трассировка")
VERDICTS = ("ПРИНЯТО", "ОТКЛОНЕНО", "ЧАСТИЧНО")
#: Полный и единственный перечень состояний находки реестра (A07,
#: контракт П0 §1.2, 12.09.2026): «патч отбракован» пишет цикл,
#: «арбитр: …» — арбитраж, «не разрешено арбитром» — §1.3
#: (противоречивые решения арбитра). Состояние «отклонено кодом»
#: остаётся в перечне ТОЛЬКО для чтения унаследованных реестров
#: (registry/1 и registry/2 до A09): по §12.8 писатель новых записей
#: его не создаёт — отбраковка замком кода сразу зреет в «тупик» вида
#: CODE_DEADLOCK_KIND. Состояние вне перечня — ошибка формы:
#: registry_update отказывает, гейт красный.
STATES = ("открыто", "принято", "отклонено", "исправлено", "закрыто",
          "тупик", "патч отбракован", "отклонено кодом",
          "арбитр: обработчик прав", "арбитр: аудитор прав",
          "арбитр: в анкету", "не разрешено арбитром")
#: Живые состояния: спор не разрешён и не закрыт. Один перечень для
#: всех читателей — цикла, панели, гейта и раннера H0 (закон живых
#: находок — функции live_findings / registry_blockers ниже).
#: «отклонено кодом» здесь — то же чтение унаследованных реестров: их
#: записи живые, и mature_legacy_code_rejections даёт им путь к
#: арбитру (§12.8).
LIVE_STATES = ("открыто", "отклонено", "патч отбракован",
               "отклонено кодом", "тупик", "не разрешено арбитром")
#: Серьёзности, чья живая находка делает «успех» цикла невозможным.
BLOCKING_SEVERITIES = ("БЛОКИРУЮЩЕЕ", "КРИТИЧЕСКОЕ")
#: Вердикт цикла: метрики чисты, но в реестре живёт Б/К-находка.
VERDICT_NOT_CLOSED = "не закрыто"
#: Закрытый перечень вердиктов завершённого цикла (гейт судит по нему).
CYCLE_VERDICTS = ("успех", "лимит", "стагнация", "остановлен по Б/К",
                  VERDICT_NOT_CLOSED)
#: ЕДИНЫЙ ИСТОЧНИК ЗАКОНА «исход заявлен» (A07-R5, согласовано с
#: COSMOS, ведомость CDPM-122): ПРЕФИКСЫ состояний прогона, которыми
#: конвейер ОБЪЯВЛЯЕТ СОБСТВЕННЫЙ ВЕРДИКТ цикла обмена. Двоеточие —
#: часть префикса: «аудит-цикл идёт» и «сквозной цикл идёт» исхода не
#: заявляют.
OUTCOME_CLAIMED_PREFIXES = (
    "аудит-цикл: ",        # «успех», «не закрыто: N блокирующих»,
                           # «лимит», «стагнация», «остановлен по Б/К»
                           # и показная «не закрыто (по реестру): …»
    "аудит остановлен: ",  # ОСТ-1: остановка по Б/К с вердиктом цикла
    "сквозной цикл: ",     # «чисто по Б/К …», «лимит кругов …»
)
#: Состояния-исходы без параметров (тот же закон, точное совпадение).
OUTCOME_CLAIMED_STATES = ("арбитраж готов",)


def outcome_claimed(state) -> bool:
    """ЗАЯВЛЯЕТ ЛИ СОСТОЯНИЕ ПРОГОНА ИСХОД ЦИКЛА ОБМЕНА — один
    предикат на всех потребителей (панель, ручка цикла, кандидаты
    заявки каталога и автоподача, оба гейта, арбитр, раннер H0).
    A07-R5, находка аудитора 12.09.2026; закон согласован с COSMOS и
    записан в ведомость CDPM-122.

    ЗАЧЕМ. Реестр находок пишет КАЖДЫЙ круг цикла
    (`run_exchange` → `_dump_registry(out_dir/"registry.json")`), и
    арбитраж переписывает его в конце. Поэтому «состояние объявило
    исход, а файла реестра нет» — это не «новый прогон» и не «споров
    нет»: реестр ИСЧЕЗ. Прежде такой прогон читался пустым реестром
    (`load_registry` → `{}`), и исчезновение носителя работало
    доказательством чистоты: панель показывала записанный «успех»,
    ручка цикла — пустой счётчик состояний, каталог — оспоренную
    строку кандидатом заявки, гейт — зелёное. Незнание успехом не
    заменяется (контракт П0 §0 п. 1) — `load_registry(path,
    expect_file=True)` отказывает словами.

    ЗАЯВЛЯЮТ ИСХОД (ровно это множество):

    - «аудит-цикл: …» — ЛЮБОЙ вердикт аудит-цикла;
    - «аудит остановлен: …» — остановка ОСТ-1 с вердиктом;
    - «сквозной цикл: …» — «чисто по Б/К …» и «лимит кругов …»;
    - «арбитраж готов» — арбитраж прошёл и переписал реестр.

    НЕ ЗАЯВЛЯЮТ (собственного вердикта цикла состояние не называет):
    «новый», «заморожено», «извлечено», «ответы применены»,
    «формализация сверена», все «… идёт», все «остановлено: …»
    (прерывание человеком посреди круга), все «отказ …» (падение
    стадии) и все «красный гейт …» (отказ ГЕЙТА, а не исход цикла).

    ВАЖНО: `False` НЕ доказывает новизны прогона — он лишь снимает
    требование файла ПО СЛОВУ СОСТОЯНИЯ. Действительную новизну
    доказывает снимок старта (`registry-start.json`) и отсутствие
    вердикта цикла; положительный контроль нового прогона держится
    именно на этом (см. тесты A07-R5).

    ЭТО ПОЛОВИНА ЗАКОНА — та, что судит СЛОВО СОСТОЯНИЯ. Состояние
    прогона меняется дальше по конвейеру: раннер H0 пересуживает цикл
    ПОСЛЕ стадии ответов, и в этот миг прогон стоит на «ответы
    применены», хотя цикл отработал раньше (проверка COSMOS на трёх
    золотых прогонах 12.09.2026). Но «ответы применены» бывает и ДО
    любого цикла (панель применяет ответы раньше обмена), поэтому
    слово состояния одно решать не вправе — вторую половину даёт
    КАТАЛОГ ОБМЕНА (`cycle_ran`), а весь закон — ОДИН предикат
    `registry_expected(exdir, state)`. Потребители зовут его, а не
    `outcome_claimed` напрямую; исключение — места, где исход известен
    точнее каталога и состояния (оба гейта, вход арбитража: там
    `expect_file=True`)."""
    if not isinstance(state, str):
        return False
    s = state.strip()
    return s in OUTCOME_CLAIMED_STATES \
        or any(s.startswith(p) for p in OUTCOME_CLAIMED_PREFIXES)


#: Семейство состояний «остановлено: <стадия>» — прерывание ЧЕЛОВЕКОМ
#: посреди стадии (кнопка «Остановить» панели; `webui._STOP_STATES`).
#: Не путать с «аудит остановлен: …» (остановка цикла ПО ПРАВИЛУ, с
#: вердиктом — заявляет исход) и с «отказ …» (падение стадии).
STOPPED_BY_HUMAN_PREFIX = "остановлено: "


def stopped_by_human(state) -> bool:
    """ОСТАНОВЛЕН ЛИ ПРОГОН ЧЕЛОВЕКОМ — один предикат для панели и
    раннера H0 (просьба COSMOS 12.09.2026 15:2x: раннер различает
    «остановлен человеком» и «отказ по правилу» не литералом панели, а
    предикатом машины состояний). Истина ровно для семейства
    «остановлено: <стадия>»; такое состояние исхода цикла НЕ заявляет
    (`outcome_claimed` — ложь) и отказом стадии НЕ является."""
    return isinstance(state, str)         and state.strip().startswith(STOPPED_BY_HUMAN_PREFIX)


#: Вердикт цикла обмена на диске: его пишет КОНЕЦ каждого цикла
#: (`run_exchange` → `_dump(out_dir/"verdict.json", …)`), и он же —
#: вход обоих гейтов и арбитража. Имя одно на весь закон A07-R5.
CYCLE_VERDICT_FILE = "verdict.json"


def cycle_ran(exdir) -> bool:
    """ОТРАБОТАЛ ЛИ ЦИКЛ ОБМЕНА В ЭТОМ КАТАЛОГЕ — предметная половина
    закона A07-R5: свидетельство берётся не со слова состояния, а с
    диска. Вердикт цикла (`verdict.json`) пишет КОНЕЦ цикла, а реестр
    (`registry.json`) — КАЖДЫЙ его круг. Значит вердикт на месте, а
    реестра нет — носитель ИСЧЕЗ, каким бы словом ни звался прогон.

    ЗАЧЕМ ОТДЕЛЬНО ОТ `outcome_claimed`. Раннер H0 пересуживает цикл
    ПОСЛЕ стадии ответов: цикл отработал и записал
    `exchange/registry.json`, затем применились ответы и состояние
    прогона стало «ответы применены» (проверка COSMOS на трёх золотых
    прогонах, 12.09.2026). По слову состояния требования носителя нет
    — исчезнувший реестр читался бы пустым («чисто») и давал ложный
    успех. Обратное тоже верно: «ответы применены» бывает и ДО всякого
    цикла (в панели ответы применяются раньше обмена), и требовать там
    реестр нельзя. Спор решает КАТАЛОГ, а не слово.

    FAIL-CLOSED, как у A07-R3. Судим не `is_file()`, а попытку узнать
    о пути (`stat`), и молчаливо ошибку ввода-вывода не глотаем:

    - пути НЕТ (`FileNotFoundError`) — цикла не было: `False`. Это
      единственная дорога к «реестра законно нет», и она же держит
      положительный контроль действительно нового прогона;
    - путь ЕСТЬ (файл, каталог с именем verdict.json, что угодно) —
      `True`: место вердикта занято, чистым такой каталог не считаем;
    - узнать не удалось (отказ доступа, сбой ввода-вывода, любая иная
      `OSError`) — `True`. «Не удалось узнать, был ли цикл» — это не
      «цикла не было»: незнание успехом не заменяется (контракт П0 §0
      п. 1). Требование носителя тогда лишь строже, а сам реестр
      читает `load_registry`, называющий свою беду своими словами."""
    p = Path(exdir) / CYCLE_VERDICT_FILE
    try:
        p.stat()
    except FileNotFoundError:
        return False
    except OSError:
        return True                    # незнание — не «цикла не было»
    return True


def registry_expected(exdir, state=None) -> bool:
    """ОБЯЗАН ЛИ РЕЕСТР НАХОДОК СУЩЕСТВОВАТЬ — ЕДИНСТВЕННЫЙ предикат
    закона A07-R5 и единственное, что зовут потребители (панель и
    список прогонов, ручка состояния цикла, кандидаты заявки каталога
    с автоподачей и кнопкой строки, продолжение цикла, раннер H0).
    Закон согласован с COSMOS (ведомость CDPM-122) и уточнён его
    проверкой на трёх золотых прогонах 12.09.2026.

    ЗАКОН ИЗ ДВУХ ЧАСТЕЙ, «ИЛИ»::

        registry_expected(exdir, state)
            = outcome_claimed(state) or cycle_ran(exdir)

    - СЛОВО: прогон сам объявил вердикт цикла («аудит-цикл: …»,
      «аудит остановлен: …», «сквозной цикл: …», «арбитраж готов»);
    - КАТАЛОГ: в `exdir` лежит вердикт цикла (`verdict.json`) —
      цикл отработал, сколько бы стадий прогон ни прошёл после него.

    Достаточно ЛЮБОЙ половины. Одной первой мало: раннер H0 судит
    цикл после стадии ответов, и состояние там — «ответы применены».
    Одной второй мало: вердикт пишется в конце цикла, а состояния
    «аудит-цикл: …» прогон достигает и на пути к нему.

    ОТРИЦАНИЕ — не доказательство новизны, а лишь снятие требования
    носителя: `False` означает «ни слово, ни каталог исполненного
    цикла не показывают». Действительную новизну доказывают
    отсутствие вердикта и снимок старта `registry-start.json`,
    который требования файла не несёт НИКОГДА (у первой ревизии его
    законно нет).

    ВЫЗОВ — всегда парой с загрузчиком::

        ex.load_registry(reg_path,
                         expect_file=ex.registry_expected(
                             reg_path.parent, state))

    Ровно эта ОДНА строка нужна и раннеру H0 на стороне COSMOS
    (`reg_path.parent` — каталог `exchange` прогона, `state` — слово
    из `status.json`; `state` можно не передавать, тогда судит только
    каталог). Гейт цикла, гейт арбитража и вход арбитража зовут
    `expect_file=True` без предиката: туда приходят ТОЛЬКО с
    исполненным циклом (его вердикт прочитан выше по тексту
    проверки)."""
    return outcome_claimed(state) or cycle_ran(exdir)


#: A07-F1 (находка аудитора 12.09.2026): причина отбраковки принятого
#: ответа, за которым нет исполненной правки. Пустое обещание не
#: превращает находку в исправленную: она остаётся живой («патч
#: отбракован») с этой причиной — и в цикле, и в повторной проводке
#: гейта (причина записана в patch-rejections.json раунда).
EMPTY_PROMISE_REASON = (
    "принято без исполненной правки: заплаты нет или она не применилась "
    "(patch / kind_patch / question_patch отсутствуют, пусты или не "
    "приняты) — обещание исправлением не является")
#: A07-F1 (четвёртое неавтор-ревью 12.09.2026, находка 1): причина
#: отбраковки принятого ответа, чья заплата ЗАЯВЛЕНА и даже
#: применилась, но не оставила СЛЕДА в новой версии свода (добор
#: ссылки, которая у вопроса уже стоит; заплата строки слово в слово
#: прежняя). Исполнение судится следом в версии — ОДНИМ законом у
#: цикла и у повторной проводки гейта (`executed_by_trace`), поэтому
#: наличие формы заплаты само по себе находку не закрывает.
#: Слова — те же, какими исполнение судит арбитраж («заплата не меняет
#: строку», `run_arbiter`): закон следа один на оба пути.
NO_TRACE_REASON = (
    "заплата без следа: правка ничего не изменила в версии свода — "
    "заплата не меняет строку, её вид, цели вопроса или анкету; "
    "принятый ответ исправлением не является")
#: A07-F1 (пятое неавтор-ревью 12.09.2026, находка 2): причина
#: отбраковки заплаты, которая возвращает строку к редакции НАЧАЛА
#: круга, уже переправленной другим принятым ответом того же обмена.
#: След судится ПОКАЗНО — по каждой заплате в момент применения, —
#: поэтому откат виден сразу: применить его значило бы стереть след
#: настоящего исправления и отдать «заплату без следа» ему, а не
#: копии прежней строки.
ROLLBACK_REASON = (
    "заплата откатывает исправление того же обмена: строка "
    "возвращается к редакции начала круга, которую уже переправил "
    "другой принятый ответ — правьте текущую редакцию строки")
#: Версия схемы реестра находок (П0 §0.1). Отсутствие поля — старая
#: форма registry/1: читается как прежде (ключи нормализует
#: normalize_registry_keys), вердикт по ней пересчитывается новым
#: законом при следующем чтении.
REGISTRY_SCHEMA = "registry/2"
ARBITER_VERDICTS = ("обработчик прав", "аудитор прав", "в анкету")
# Метрика считает только весомые серьёзности; редакционные — счётчиком
# E, в останове не участвуют.
_COUNTED = {"БЛОКИРУЮЩЕЕ": "B", "КРИТИЧЕСКОЕ": "K", "СЕРЬЁЗНОЕ": "S",
            "РЕДАКЦИОННОЕ": "E"}

#: Классы замечаний, которые берут величину задания по величинам на
#: себя (замок содержания): «пропуск» — строки по клаузе нет,
#: «искажение» — строка есть, величину не несёт. Прочие классы
#: величину не адресуют.
VALUE_REMARK_CLASSES = ("пропуск", "искажение")

CLEAN_NEEDED = 2      # чистых аудитов подряд для успеха (протокол
                      # пилотной линии)
STALL_ROUNDS = 2      # обменов без улучшения метрики до вердикта
                      # «стагнация»


#: Вопросы, которые строит КОД (по книге данных или по обнаружению
#: критерия), а не обработчик: линия данных (нет данных / значения вне
#: перечня / история) и вопросы о целевой. Замечание аудитора к их тексту
#: адресуется коду, не обработчику: оно отбраковывается на приёме, а не
#: живёт в реестре кругами до тупика (живой прогон простого Н0 05.09: три
#: круга «заплата вопроса Q-3b-история-нет» — строка «цикл не чист» при
#: верном пакете).
CODE_BUILT_QUESTION_PREFIXES = ("Q-3a-нет-данных-", "Q-3b-нет-данных-",
                                "Q-3a-данные-", "Q-3b-данные-", "Q-3b-история-",
                                "Q-3a-GOAL", "Q-3b-GOAL",
                                # полнота параметров семьи (09.09.2026)
                                "Q-3a-параметр-", "Q-3b-параметр-")


def is_code_built_question(qid) -> bool:
    return str(qid or "").startswith(CODE_BUILT_QUESTION_PREFIXES)


def validate_remarks(pack: dict, doc: dict) -> list[str]:
    """Пакет замечаний аудитора против модели свода. Все нарушения
    разом; каждое сообщение адресует замечание."""
    problems: list[str] = []
    known_rules = {r["id"] for r in doc.get("rules", [])}
    known_questions = {q["id"] for q in doc.get("questions", [])}
    known_sids = {s["sid"] for s in doc.get("sources", [])}
    seen: set[str] = set()
    for i, rm in enumerate(pack.get("remarks", [])):
        rid = rm.get("id", "<без id>")
        # Нестроковый id (живой урок UniA run-0051: аудитор вернул
        # словарь) — проблема гейта, не падение на хэшировании.
        if not isinstance(rid, str):
            problems.append(f"замечание #{i}: id не строка: {rid!r}")
            continue
        # Пустой id (ревью блока неизменности id, 1.09): перечень
        # допустимых номеров порции обработчика фильтрует пустые —
        # валидатор обязан резать их у истока, иначе validate_response
        # требует ответ на номер, которого в перечне нет.
        if not rid.strip():
            problems.append(f"замечание #{i}: пустой id")
            continue
        if rid in seen:
            problems.append(f"{rid}: повторный идентификатор замечания")
        seen.add(rid)
        if rm.get("severity") not in SEVERITIES:
            problems.append(f"{rid}: серьёзность {rm.get('severity')!r} "
                            f"вне перечня {SEVERITIES}")
        if rm.get("defect_class") not in DEFECT_CLASSES:
            problems.append(f"{rid}: класс {rm.get('defect_class')!r} "
                            f"вне перечня {DEFECT_CLASSES}")
        target = rm.get("target") or {}
        t_rule, t_q = target.get("rule"), target.get("question")
        if t_rule is not None and not isinstance(t_rule, str):
            problems.append(f"{rid}: адрес строки не строка: "
                            f"{t_rule!r}")
            t_rule = None
        if t_q is not None and not isinstance(t_q, str):
            problems.append(f"{rid}: адрес вопроса не строка: {t_q!r}")
            t_q = None
        if t_rule and t_rule not in known_rules:
            problems.append(f"{rid}: адресует несуществующую строку "
                            f"{t_rule!r}")
        if t_q and t_q not in known_questions:
            problems.append(f"{rid}: адресует несуществующий вопрос "
                            f"{t_q!r}")
        elif t_q and is_code_built_question(t_q):
            problems.append(f"{rid}: вопрос {t_q} строится кодом (линия "
                            f"данных / целевая) — его текст и ссылки не "
                            f"предмет обмена с обработчиком; замечание "
                            f"адресуется коду, не своду")
        if not t_rule and not t_q and rm.get("defect_class") != "пропуск":
            # Без адреса законен только «пропуск»: его строки в своде
            # по определению нет.
            problems.append(f"{rid}: замечание без адреса допустимо "
                            f"только для класса «пропуск»")
        srefs = rm.get("source_refs") or []
        if not srefs:
            problems.append(f"{rid}: замечание без трассировки к "
                            f"источникам не существует")
        for ref in srefs:
            sid = ref.get("sid") if isinstance(ref, dict) else ref
            if not isinstance(sid, str):
                problems.append(f"{rid}: трассировка с нестроковым "
                                f"sid: {sid!r}")
            elif sid not in known_sids:
                problems.append(f"{rid}: трассировка на неизвестный "
                                f"источник {sid!r}")
        if not (rm.get("text") or "").strip():
            problems.append(f"{rid}: пустая суть замечания")
        if not (rm.get("evidence") or "").strip():
            problems.append(f"{rid}: замечание без доказательства — "
                            f"цитаты источника")
    return problems


def validate_response(resp: dict, pack: dict) -> list[str]:
    """Ответ обработчика против пакета замечаний: полнота и основания."""
    problems: list[str] = []
    remark_ids = [rm.get("id") for rm in pack.get("remarks", [])
                  if isinstance(rm.get("id"), str)]
    answered: set[str] = set()
    for i, a in enumerate(resp.get("answers", [])):
        if not isinstance(a, dict):
            problems.append(f"ответ #{i} не объект: {repr(a)[:40]}")
            continue
        rid = a.get("remark", "<без ссылки>")
        if not isinstance(rid, str):
            problems.append(f"ответ #{i}: ссылка на замечание не "
                            f"строка: {rid!r}")
            continue
        if rid not in remark_ids:
            problems.append(f"{rid}: ответ на несуществующее замечание")
            continue
        if rid in answered:
            problems.append(f"{rid}: повторный ответ на замечание")
        answered.add(rid)
        v = a.get("verdict")
        if v not in VERDICTS:
            problems.append(f"{rid}: вердикт {v!r} вне перечня "
                            f"{VERDICTS}")
            continue
        if not (a.get("basis") or "").strip():
            # Принятие обязано цитировать источник так же, как
            # отклонение, — защита от уступчивости.
            problems.append(f"{rid}: ответ без основания-цитаты")
        if v in ("ПРИНЯТО", "ЧАСТИЧНО") and \
                not (a.get("change") or "").strip():
            problems.append(f"{rid}: вердикт {v} без описания "
                            f"изменения")
    missing = sorted(set(remark_ids) - answered)
    for rid in missing:
        problems.append(f"{rid}: замечание осталось без ответа")
    return problems


def metrics_of(pack: dict) -> dict:
    """Метрика аудита: счётчики по серьёзностям из пакета замечаний.
    Только весомые (Б, К, С) участвуют в останове."""
    counts = {"B": 0, "K": 0, "S": 0, "E": 0}
    for rm in pack.get("remarks", []):
        key = _COUNTED.get(rm.get("severity"))
        if key:
            counts[key] += 1
    counts["weighty"] = (counts["B"], counts["K"], counts["S"])
    # Замок биекции «не потерять» (4П, 2026-09-02): клаузы задания
    # полноты, оставшиеся без вердикта аудитора (ни «пропуск», ни
    # «не правило»), — часть метрики раунда; «успех» при них невозможен.
    counts["coverage_missing"] = len(pack.get("coverage_missing") or [])
    # Замок содержания (аудит 2026-09-04, п. 2): величины задания по
    # величинам без замечания и без вердикта — та же природа: «успех»
    # при них невозможен (пакет с таким остатком не выпускается).
    counts["coverage_values_missing"] = len(
        pack.get("coverage_values_missing") or [])
    return counts


def live_findings(registry: dict | None) -> list[dict]:
    """Живые находки реестра — единственный предикат для панели
    (бэклог серьёзных, кандидаты заявок), сквозного цикла, гейта и
    раннера (A07, контракт П0 §1.2): состояние из LIVE_STATES, без
    closed_round, и ключ не решён арбитром. Ключ, решённый арбитром,
    гасит ВСЕ находки этого ключа: пока спор зрел до тупика, каждый
    повтор открывал отдельную находку — после вердикта они не спор, а
    его эхо (решение обязательно для обеих сторон).

    Читает реестр ПОСЛЕ миграции чтения (`normalize_registry`, A07-F3):
    старая техническая отбраковка замком кода с проставленным
    closed_round живой и остаётся живой, даже если вызывающий забыл
    нормализовать. Вход не меняется — функция чистая."""
    findings = normalize_registry(registry).get("findings", [])
    resolved = {f.get("key") for f in findings
                if f.get("key")
                and str(f.get("state", "")).startswith("арбитр: ")}
    return [f for f in findings
            if f.get("state") in LIVE_STATES
            and f.get("closed_round") is None
            and f.get("key") not in resolved]


def registry_blockers(registry: dict | None) -> list[dict]:
    """Живые находки блокирующей/критической серьёзности — те, при
    которых вердикт «успех» невозможен (A07). Закрывает находку только
    closed_round по принятому и исполненному патчу либо решение
    арбитра; молчание аудитора в следующем раунде закрытием не
    считается."""
    return [f for f in live_findings(registry)
            if f.get("severity") in BLOCKING_SEVERITIES]


def registry_verdict_of(registry: dict | None) -> dict:
    """Сводка блокирующих для verdict.json (всегда присутствует, при
    чистом реестре — пустой перечень): {"blockers": [{id, severity,
    state, opened_round}], "count": n}."""
    blockers = [{"id": f.get("id"), "severity": f.get("severity"),
                 "state": f.get("state"),
                 "opened_round": f.get("opened_round")}
                for f in registry_blockers(registry)]
    return {"blockers": blockers, "count": len(blockers)}


def verdict_by_registry(stored_verdict, registry: dict | None) -> str:
    """A07, миграция показа старых циклов: записанный «успех» — и
    «остановлен по Б/К», который с A07 тоже невозможен при живом
    блокере, — при живой блокирующей/критической находке реестра
    показывается как «не закрыто (по реестру)»; любой другой
    записанный вердикт — как записан. Чистая функция: файлы истории
    не переписывает, судит только по переданному реестру."""
    words = str(stored_verdict)
    if words in ("успех", "остановлен по Б/К") and registry_blockers(registry):
        return VERDICT_NOT_CLOSED + " (по реестру)"
    return words


def decide(history: list[dict], max_rounds: int,
           registry: dict | None) -> str:
    """Правило останова по истории метрик (в порядке обменов):

    - «успех» — CLEAN_NEEDED чистых аудитов подряд ((0,0,0)) И (при
      переданном реестре) пустой registry_blockers(registry);
    - «не закрыто» — метрики дают успех, но в реестре живёт
      блокирующая/критическая находка (A07, контрпример CONS-02:
      критическая находка с отбракованным патчем и два «чистых»
      раунда молчания аудитора прежде давали «успех»);
    - «лимит» — обменов не меньше max_rounds;
    - «стагнация» — STALL_ROUNDS обменов подряд без улучшения
      лексикографической метрики (аудитор вправе находить новое — рост
      не провал, но повод остановиться и показать владельцу);
    - иначе «продолжать».

    `registry=None` — прежнее правило по одним метрикам (устаревшие
    вызовы и самотест гейта); производственные вызовы — цикл, панель,
    гейт — передают реестр."""
    if not history:
        return "продолжать"
    weighty = [tuple(h["weighty"]) for h in history]
    tail_h = history[-CLEAN_NEEDED:]
    # АЦ-4/Е1: успех — два чистых аудита подряд, причём ПОСЛЕДНИЙ
    # обязан быть полным: чистота инкрементального раунда сама по
    # себе — не доказательство, финал подтверждается полным проходом.
    if len(tail_h) >= CLEAN_NEEDED and all(
            tuple(h["weighty"]) == (0, 0, 0) for h in tail_h) \
            and tail_h[-1].get("mode", "полный") == "полный" \
            and not (tail_h[-1].get("coverage_missing") or 0) \
            and not (tail_h[-1].get("coverage_values_missing") or 0):
        # Замок биекции: полный чистый аудит с клаузами без вердикта
        # покрытия успехом не является — полнота не подтверждена.
        # Замок реестра (A07): успех невозможен при живой Б/К-находке
        # — правка не встала или спор не разрешён.
        if registry is not None and registry_blockers(registry):
            return VERDICT_NOT_CLOSED
        return "успех"
    if len(history) >= max_rounds:
        return "лимит"
    # Чистое плато (0,0,0) — не стагнация: цикл ждёт полного
    # подтверждающего аудита (АЦ-4/Е1).
    if len(weighty) > STALL_ROUNDS and weighty[-1] != (0, 0, 0):
        recent = weighty[-(STALL_ROUNDS + 1):]
        if all(recent[i + 1] >= recent[i] for i in range(STALL_ROUNDS)):
            return "стагнация"
    return "продолжать"


# С-2 (анализ Лайта-v3, круг 3): один спор о ВОПРОСЕ АНКЕТЫ приходил
# под классами-синонимами («пропуск» в р1, «потерянная трассировка» в
# р5) — ключи расходились, счётчик «отклонено и повторено» не зрел и
# спор не дошёл до арбитра. Классы нехватки сводятся к одному бакету
# КЛЮЧА только для замечаний, адресующих вопрос анкеты: там «не
# хватает ссылок вопроса» — одна претензия. Для строк свода классы НЕ
# сливаются: «пропуск по строке» и «потерянная трассировка строки» —
# разные дефекты, слияние рождало бы ложные тупики и ложное подавление
# вердиктов арбитра (вердикт состязательной проверки 2026-08-21).
# Класс самого замечания не меняется (потолки Г1 читают оригинал).
_KEY_CLASS_EQUIV = {"потерянная трассировка": "пропуск"}


def remark_key(rm: dict) -> str:
    """Ключ замечания — каноническая строка JSON (хэшируема, переживает
    диск байт-в-байт); безадресный «пропуск» различается местом
    источника."""
    t = rm.get("target") or {}
    anchor = None
    if not t.get("rule") and not t.get("question"):
        # АЦ-4/А2: безадресный «пропуск» различается ПОЛНЫМ набором
        # якорей (сортированным) — первый якорь давал разные ключи
        # одному пропуску, и тупики не зрели.
        refs = rm.get("source_refs") or []
        anchor = sorted([r.get("sid"), r.get("anchor")]
                        for r in refs)
    klass = rm.get("defect_class")
    if rm.get("fit_dispute"):
        # Спор посадки отличим от органического «искажения» той же
        # строки (ревью пакета): чужой арбитраж не должен давить
        # будущие споры посадки, и наоборот.
        klass = f"{klass}+посадка"
    if t.get("question") and not t.get("rule"):
        klass = _KEY_CLASS_EQUIV.get(klass, klass)
    return json.dumps([klass, t.get("rule"),
                       t.get("question"), anchor], ensure_ascii=False)


def strip_anchor_brackets(anchor) -> str:
    """Якорь из ответа модели без обрамляющих скобок листинга («[абз.3]»
    → «абз.3»): прогон №5 H0 — аудитор трассировал в «[абз.3]», поиск
    текста клаузы по такому якорю давал «<нет>», и арбитр судил по
    отсутствующему тексту."""
    a = str(anchor or "").strip()
    if a.startswith("[") and a.endswith("]"):
        a = a[1:-1].strip()
    return a


# Причины отбраковки заплаты, которые говорят о СОДЕРЖАНИИ правки
# (замок или конвенция кода), а не о её форме: находка с такой причиной
# терминальна — повтор того же замечания отбраковывается до обработчика
# (план «прямой ход» 2.5; прогон №5 H0: пять кругов подряд один и тот же
# параметр вне семьи).
_TERMINAL_REJECTION_MARKERS = (
    "принадлежит ни одной семье", "вне перечня миграций",
    "уже потреблена целевой", "понижение посадки", "смена семьи",
    "потеря параметр", "уменьшает информацию", "«выбор чтения»",
    "снята заплатой целиком",
)


def omission_closed_by_code(rm: dict, verdicts: dict | None) -> str | None:
    """«Пропуск» по клаузам, закрытым вердиктом КОДА (стадия структуры:
    титул, валюта и база, канон композиции, заголовки, пусто), — не
    пропуск: вердикт кода первичен, спор о нём — не аудитору. Проход №8
    H0: три круга «конструкция целевой функции S1 не отражена записью»
    по клаузе канона композиции, обработчик рождал строки с зоной
    «объективная функция». Возвращает причину отбраковки либо None."""
    if rm.get("defect_class") != "пропуск" or not verdicts:
        return None
    refs = [(r.get("sid"), strip_anchor_brackets(r.get("anchor")))
            for r in (rm.get("source_refs") or []) if isinstance(r, dict)]
    if not refs:
        return None
    reasons = []
    for k in refs:
        v = verdicts.get(k) or verdicts.get((k[0], f"[{k[1]}]")) or {}
        if v.get("by") != "code":
            return None
        reasons.append(f"{k[1]}: {v.get('reason')}")
    return ("клаузы закрыты вердиктом кода (стадия структуры): "
            + "; ".join(reasons) + " — пропуском не являются")


def code_terminal_closures(patch_rejected: list | None, pack: dict) -> dict:
    """Ключи замечаний, чьи заплаты отвергнуты замком/конвенцией кода →
    причина запрета повтора. Форменные отказы (не объект, несуществующая
    строка, цитата не из клаузы) терминальными не считаются: обработчик
    вправе исправить форму в следующем круге."""
    by_id = {rm.get("id"): rm for rm in pack.get("remarks", [])
             if isinstance(rm, dict)}
    out: dict = {}
    for rj in patch_rejected or []:
        if not isinstance(rj, dict):
            continue
        reasons = [str(r) for r in (rj.get("reasons") or [])]
        if not any(mk in r for r in reasons for mk in _TERMINAL_REJECTION_MARKERS):
            continue
        rm = by_id.get(rj.get("answer"))
        if rm is None:
            continue
        out[remark_key(rm)] = ("требование замка кода: " + "; ".join(reasons)
                               + " — повторное указание запрещено (состояние "
                                 "терминально)")
    return out


#: Вид тупика, в который дозревает находка, чью заплату терминально
#: отверг замок/конвенция кода (§12.8 контракта П0, слово владельца
#: «Вариант 1» 12.09.2026). Рядом с прежними видами «повтор»,
#: «частично», «осцилляция»: способ созревания разный, исход один —
#: спор, который ни одна сторона не вправе решить сама.
CODE_DEADLOCK_KIND = "отклонено кодом"
#: Причина для унаследованной записи, у которой слов замка не
#: сохранилось: досье арбитра обязано что-то показать, и «нет причины»
#: — это тоже названный словами факт, а не пустая строка.
LEGACY_CODE_REJECTION = ("замок кода отверг заплату обработчика "
                         "(унаследованная запись реестра: слова замка "
                         "не сохранены)")


def mark_code_rejected(registry: dict, closed_now: dict,
                       round_no: int) -> list[str]:
    """Замок/конвенция кода терминально отверг заплату обработчика.

    A07 (контракт П0 §1.2/§1.5) сделал такую находку ЖИВОЙ: её никто
    не исполнил и не рассудил, поэтому closed_round не ставится и
    Б/К-находка держит «не закрыто». §12.8 (слово владельца «Вариант
    1», 12.09.2026) даёт ей выход: дозревание НЕМЕДЛЕННОЕ — ни одна
    сторона действовать не вправе (повтор замечания аудитором запрещён
    машинно через arbiter_closed, заплата обработчика незаконна), —
    поэтому находка сразу получает состояние «тупик» с
    `deadlock_kind = CODE_DEADLOCK_KIND`, сохраняя номер круга
    отбраковки (`code_rejected_round`) и слова замка (`code_rejection`)
    для досье арбитра. Дорожка одна для всех серьёзностей; «не
    закрыто» по-прежнему держат только Б/К.

    Записи «закрыто» и решения арбитра («арбитр: …») не трогаются:
    отбраковка заплаты не отменяет ни исполненного закрытия, ни
    рассуженного спора.

    Спор, УЖЕ дошедший до арбитра («тупик» любого вида и «не разрешено
    арбитром»), состояния не меняет (ревью A09, находка 7): прежде
    писатель безусловно ставил «тупик», и «не разрешено арбитром»
    теряло сам факт состоявшегося разбирательства (причина оставалась
    в `arbiter_unresolved` полем-сиротой, на которое больше никто не
    смотрел), а виды «повтор» и «осцилляция» — свою историю созревания.
    Замок кода добавляет к такому спору СВОЙ след, ничего не стирая:
    прежний вид сохраняется словами в `deadlock_kind_before_code`, а
    сам вид становится «отклонено кодом» — иначе арбитр, не увидев
    запрета, велел бы написать заплату, которой не существует.

    ПЕРВЫЕ слова замка не затираются вторым запретом по тому же спору
    (ревью A09 №2, находка 7): `code_rejection` и `code_rejected_round`
    держат первый запрет, а каждый следующий дописывается историей в
    `code_rejection_history` ([{круг, слова}]). Прежде второй замок
    переписывал поля, и досье арбитра теряло слова, которыми спор
    дозрел до тупика, — арбитр судил по последней формулировке, не
    видя, с чего запрет начался.

    Возвращает ключи помеченных находок."""
    marked = []
    for f in registry.get("findings", []):
        key = f.get("key")
        if key not in closed_now:
            continue
        state = str(f.get("state") or "")
        if state == "закрыто" or state.startswith("арбитр: "):
            continue
        _remember_code_rejection(f, closed_now.get(key), round_no)
        if state in ("тупик", "не разрешено арбитром"):
            kind = f.get("deadlock_kind")
            if kind and kind != CODE_DEADLOCK_KIND:
                f["deadlock_kind_before_code"] = kind
            f["deadlock_kind"] = CODE_DEADLOCK_KIND
            marked.append(key)
            continue
        f["state"] = "тупик"
        f["deadlock_kind"] = CODE_DEADLOCK_KIND
        f["closed_round"] = None
        f["closed_by"] = None
        marked.append(key)
    return marked


def _remember_code_rejection(finding: dict, words, round_no) -> None:
    """Слова замка кода при находке: первые сохраняются навсегда,
    каждые следующие дописываются историей (ревью A09 №2, находка 7)."""
    first = str(finding.get("code_rejection") or "").strip()
    history = finding.get("code_rejection_history")
    if not isinstance(history, list):
        history = []
    if first and not history:
        # Первый запрет мог быть записан прежним кодом, без истории:
        # заводим её задним числом из сохранённых полей.
        history = [{"round": finding.get("code_rejected_round"),
                    "reason": finding["code_rejection"]}]
    now = {"round": round_no, "reason": words}
    if now not in history:
        history.append(now)
    if len(history) > 1:
        finding["code_rejection_history"] = history
    if not first:
        finding["code_rejection"] = words
        finding["code_rejected_round"] = round_no


def mature_legacy_code_rejections(registry: dict | None,
                                  round_no: int | None = None,
                                  normalized: bool = False) -> dict:
    """Унаследованная запись «отклонено кодом» — тот же тупик (§12.8).

    Чистая функция: возвращает НОВЫЙ реестр, вход не меняется, файлы
    не пишутся. До 12.09.2026 писатель оставлял такую находку в
    состоянии «отклонено кодом» — живом (A07), но без пути
    разрешения: арбитраж берёт только «тупик». Закон дозревания один и
    для новых отбраковок (`mark_code_rejected`), и для старых записей,
    иначе прогоны, сделанные вчера, остались бы без арбитра навсегда.

    ПОРЯДОК ВЫЗОВА ОБЯЗАТЕЛЕН (ревью A09, находка 4): сразу ПОСЛЕ
    нормализации чтения реестра (`normalize_registry`, A07 — шаг 2) и
    ДО расчёта живых находок, вердикта цикла и перечня тупиков.
    Единственный судья закрытости унаследованной записи — нормализация:
    у ЖИВОЙ технической отбраковки замком кода она снимает
    `closed_round`, сохраняя прежний номер в
    `legacy_code_closure_round`. Своей проверки закрытости этот
    помощник не заводит — он лишь читает следы нормализации, и порядок
    вызовов ровно поэтому не переставляется.

    Запись считается ЖИВОЙ по любому из трёх следов:

    - `normalized=True` — нас позвали сразу после нормализации:
      судить закрытость заново нечем и незачем, всё оставшееся в
      состоянии «отклонено кодом» живое;
    - есть `legacy_code_closure_round` — след самой нормализации,
      переживший запись реестра на диск (по нему запись узнаётся и
      при вызове «на холодную», без флага);
    - `closed_round is None` — реестр уже приведён к живому виду.

    Запись с проставленным `closed_round` и БЕЗ обоих следов — закрытая
    запись старой формы: её читают как есть, не воскрешают. У
    дозревшей записи `closed_round` снимается (тупик закрытым быть не
    может), а снятый номер сохраняется в `legacy_code_closure_round`.
    Номер круга отбраковки и слова замка восстанавливаются из того,
    что сохранилось; `round_no` — последнее средство, когда не
    сохранилось ничего.

    Возвращает новый реестр; руководство 10.7, подраздел «Тупик,
    дозревший из отбраковки замком кода»."""
    reg = dict(registry or {})
    findings = []
    for f in (reg.get("findings") or []):
        if not isinstance(f, dict) \
                or f.get("state") != CODE_DEADLOCK_KIND:
            findings.append(f)
            continue
        legacy_round = f.get("legacy_code_closure_round")
        alive = (normalized or legacy_round is not None
                 or f.get("closed_round") is None)
        if not alive:
            findings.append(f)
            continue
        item = dict(f)
        item["state"] = "тупик"
        item["deadlock_kind"] = CODE_DEADLOCK_KIND
        if item.get("closed_round") is not None:
            # Тупик закрытым быть не может: номер уходит туда же, куда
            # его кладёт нормализация, — историей, а не признаком.
            if legacy_round is None:
                legacy_round = item["closed_round"]
                item["legacy_code_closure_round"] = legacy_round
            item["closed_round"] = None
            item["closed_by"] = None
        if item.get("code_rejected_round") is None:
            item["code_rejected_round"] = (
                legacy_round if legacy_round is not None else round_no)
        if not str(item.get("code_rejection") or "").strip():
            item["code_rejection"] = LEGACY_CODE_REJECTION
        findings.append(item)
    if "findings" in reg or findings:
        reg["findings"] = findings
    return reg


def reopen_unresolved_disputes(registry: dict) -> list[str]:
    """Спор, оставшийся «не разрешено арбитром», входит в НОВЫЙ
    мегакруг тупиком (ревью A09, находка 3).

    Состояние «не разрешено арбитром» ставит арбитраж своего цикла и
    судит по своему `verdict.json`. Перенесённое в следующий мегакруг
    как есть, оно оказывалось спором БЕЗ ПУТИ: тупиком оно не
    считается, значит, в новый `verdict.json` не попадает; `run_arbiter`
    берёт разбирательства только по этому перечню; а ручной возврат в
    «тупик» краснил гейт словами «вердикт по неизвестному тупику».
    Живая находка держала цикл в «не закрыто» вечно.

    Поэтому на старте нового мегакруга такая находка возвращается в
    «тупик» — как всякий неразрешённый спор, — и новый цикл честно
    предъявляет её арбитру. История разбирательства не теряется:
    причина неразрешённости остаётся при находке полем
    `arbiter_unresolved`, вид тупика (в том числе «отклонено кодом»,
    §12.8) — полем `deadlock_kind`.

    Меняет реестр на месте, возвращает id возвращённых находок."""
    reopened = []
    for f in registry.get("findings", []):
        if f.get("state") != "не разрешено арбитром":
            continue
        f["state"] = "тупик"
        reopened.append(f.get("id"))
    return reopened


def _normalize_key(key: str) -> str:
    """Ключ находки прежней ревизии — к текущей канонизации: классы-
    синонимы (только адрес-вопрос) и якорный формат до АЦ-4/А2
    (плоская пара [sid, anchor] → список пар; полный набор якорей
    многоякорной находки утрачен прежним кодом — непрерывность для
    неё честно рвётся). Нечитаемый ключ возвращается как есть (не
    падать на мусоре)."""
    try:
        parts = json.loads(key or "[]")
    except (ValueError, TypeError):
        return key
    if not isinstance(parts, list) or len(parts) < 4:
        return key
    changed = False
    if parts[2] and not parts[1] and parts[0] in _KEY_CLASS_EQUIV:
        parts[0] = _KEY_CLASS_EQUIV[parts[0]]
        changed = True
    anchor = parts[3]
    if isinstance(anchor, list) and anchor \
            and all(isinstance(x, str) or x is None for x in anchor):
        parts[3] = [anchor]
        changed = True
    if changed:
        return json.dumps(parts, ensure_ascii=False)
    return key


def normalize_registry_keys(registry: dict) -> int:
    """С-2: миграция реестра прежних ревизий — без неё находка со
    старым ключом никогда не совпала бы с новым замечанием и
    непрерывность Ж3 рвалась бы на классах-синонимах. Возвращает число
    переписанных ключей."""
    n = 0
    for f in registry.get("findings", []):
        k2 = _normalize_key(f.get("key", ""))
        if k2 != f.get("key"):
            f["key"] = k2
            n += 1
    return n


#: Причина возврата унаследованной записи в живые (A07-F3): прежний код
#: (ed53ef3a) сам ставил отвергнутой замком заплате
#: `state="отклонено кодом", closed_round=<раунд>, closed_by="замок
#: кода"`. Это не исполненный патч и не решение арбитра, а техническая
#: отбраковка — закрытием она не является.
LEGACY_CODE_CLOSURE = "замок кода"


def normalize_registry(registry: dict | None) -> dict:
    """Единственная миграция реестра при ЧТЕНИИ (A07, контракт П0 §1.2;
    находка аудитора A07-F3): возвращает НОВЫЙ реестр — вход не
    меняется, файлы на диске чтением не переписываются.

    1. Ключи находок — к текущей канонизации (`normalize_registry_keys`).
    2. Старая техническая отбраковка замком кода отличается от
       доказанного разрешения: запись «отклонено кодом» с
       проставленным `closed_round` — это писатель до 12.09.2026
       (`closed_by="замок кода"`), её никто не исполнил и не рассудил.
       Такая запись возвращается в ЖИВЫЕ: `closed_round=None`,
       `closed_by=None`, прежний номер сохраняется в
       `legacy_code_closure_round` (история не теряется).
    3. Настоящие закрытия — `closed_round` по принятому и ИСПОЛНЕННОМУ
       патчу (состояние «закрыто») — и решения арбитра
       («арбитр: …») не трогаются: переоткрывать их нечем и незачем.

    Закон один для всех читателей: цикл, панель, гейт, сквозной цикл и
    раннер H0 судят нормализованный реестр."""
    reg = dict(registry or {})
    findings = []
    for f in (reg.get("findings") or []):
        if not isinstance(f, dict):
            findings.append(f)
            continue
        item = dict(f)
        item["key"] = _normalize_key(item.get("key", ""))
        if item.get("state") == "отклонено кодом" \
                and item.get("closed_round") is not None:
            item["legacy_code_closure_round"] = item.get("closed_round")
            item["closed_round"] = None
            if item.get("closed_by") in (LEGACY_CODE_CLOSURE, None):
                item["closed_by"] = None
        findings.append(item)
    if "findings" in reg or findings:
        reg["findings"] = findings
    return reg


def validate_registry_form(raw, where: str = "реестр находок") -> dict:
    """Форма носителя реестра ДО перезаписи и продолжения (контракт П0
    §0, п. 5; находка аудитора A07-F4). Судит ЗАЯВЛЕННАЯ версия:

    - поля нет — старая форма registry/1: читается как прежде;
    - `registry/2` — новая форма: поле `findings` обязательно и есть
      список объектов (неполная новая форма — отказ, не откат на
      старую и не миграция в пустоту);
    - любая другая версия — отказ словами (не догадка и не молчаливая
      замена версии писателем).

    Форма самого поля `findings` судится при ЛЮБОЙ версии, включая
    старую registry/1 (третье неавтор-ревью, проба P5): `{"findings":
    "abc"}` прежде проезжало проверку, разбиралось по буквам
    (`dict(reg)` над строкой) и роняло проводку AttributeError
    «'str' object has no attribute 'get'» — отказ без причины вместо
    названного отказа формы. Обязательность поля остаётся законом
    только новой формы: у registry/1 его отсутствие законно.

    A07-R2 (находка аудитора 12.09.2026), два закона формы:

    1. ОТСУТСТВИЕ КЛЮЧА и ЗАЯВЛЕННОЕ ЗНАЧЕНИЕ — не одно и то же.
       Прежде `raw.get("schema_version") is None` читал явный
       `"schema_version": null` как старую форму: негодный носитель
       проезжал молча, писатель ставил ему `registry/2` и цикл
       заканчивался «успехом». Теперь ключа нет — registry/1; ключ
       есть — его значение обязано быть ровно `REGISTRY_SCHEMA`,
       иначе отказ словами (null, false, число, строка — одинаково).
    2. ДОМЕНЫ ПОЛЕЙ, ВЛИЯЮЩИХ НА РЕШЕНИЕ, судятся ДО счёта живых и
       блокирующих находок: состояние — из закрытого перечня `STATES`
       (§1.2 контракта П0), серьёзность — из `SEVERITIES`. Иначе
       находка с чужим состоянием исчезала из живых, а находка с
       чужой серьёзностью не блокировала успех: неизвестность
       работала доказательством отсутствия спора. Отказ НАЗЫВАЕТ
       находку. Миграция чтения (`normalize_registry`) состояний не
       переименовывает — судить домены можно до неё.

    Возвращает тот же объект; отказ — `ExchangeError`."""
    if not isinstance(raw, dict):
        raise ExchangeError(f"{where}: форма не объект: {type(raw).__name__}")
    if "findings" in raw:
        if not isinstance(raw["findings"], list):
            raise ExchangeError(
                f"{where}: поле «findings» не список: "
                f"{type(raw['findings']).__name__}")
        bad = [repr(f)[:40] for f in raw["findings"]
               if not isinstance(f, dict)]
        if bad:
            raise ExchangeError(
                f"{where}: записи находок не объекты: " + summarize_items(bad, limit=3))
    if "schema_version" in raw:
        schema = raw["schema_version"]
        if schema != REGISTRY_SCHEMA:
            raise ExchangeError(
                f"{where}: неизвестная или негодная версия реестра — "
                f"версия схемы {schema!r} (известны {REGISTRY_SCHEMA!r} "
                f"и старая форма БЕЗ поля; явный null формой без поля "
                f"не является) — продолжение и перезапись отказаны")
        if "findings" not in raw:
            raise ExchangeError(
                f"{where}: неполная форма {REGISTRY_SCHEMA!r} — нет поля "
                f"«findings»; пустой реестр объявляется явно "
                f"(\"findings\": [])")
    for f in raw.get("findings") or []:
        name = f.get("id") or f.get("key") or "<без id>"
        if f.get("state") not in STATES:
            raise ExchangeError(
                f"{where}: находка {name!r}: состояние "
                f"{f.get('state')!r} вне перечня STATES "
                f"({', '.join(STATES)}) — неизвестное состояние "
                f"закрытым не считается")
        if f.get("severity") not in SEVERITIES:
            raise ExchangeError(
                f"{where}: находка {name!r}: серьёзность "
                f"{f.get('severity')!r} вне перечня SEVERITIES "
                f"({', '.join(SEVERITIES)}) — неизвестная серьёзность "
                f"неблокирующей не считается")
    return raw


def load_registry(path, *, expect_file: bool = False) -> dict:
    """Единственный загрузчик реестра находок (цикл, снимок старта,
    панель, гейт, арбитр, раннер H0). Три ИСХОДА, а не два (A07-R3,
    находка аудитора 12.09.2026):

    1. пути НЕТ (`FileNotFoundError`) — пустой реестр: единственная
       предусмотренная контрактом совместимость, новый цикл законен;
    2. путь есть, но прочитать его нечем (каталог вместо файла, отказ
       доступа, любая иная ошибка ввода-вывода) — `RegistryUnavailable`
       словами «реестр временно недоступен»; НЕ пустой реестр;
    3. прочитан — форма судится ДО использования
       (`validate_registry_form`), затем применяется миграция чтения
       (`normalize_registry`).

    Прежде судьёй было `not p.is_file()`, и каталог с именем
    registry.json, отказ доступа и сбой чтения читались как «реестра
    нет» → «живых находок нет» → чистый показ и зелёный прогон.
    «Не удалось узнать о спорах» — это не «споров нет»: незнание
    успехом не заменяется (контракт П0 §0, п. 1). Сырых деталей ОС в
    словах отказа нет — они остаются в причине исключения.

    `expect_file=True` — ЗАКОН A07-R5 (согласован с COSMOS, ведомость
    CDPM-122): ИСХОД ЗАЯВЛЕН, значит носитель обязан быть. Реестр
    пишет каждый круг цикла и переписывает арбитраж — после
    объявленного исхода «файла нет» означает не новый прогон, а
    ИСЧЕЗНУВШИЙ реестр: `RegistryMissing` словами «реестр отсутствует
    после исполненного цикла: <путь>». ОБЯЗАН ЛИ носитель быть, решает
    ОДИН предикат `registry_expected(exdir, state)` (закон из двух
    частей: слово состояния `outcome_claimed` ИЛИ вердикт цикла в
    каталоге `cycle_ran`) — потребители зовут
    `load_registry(path, expect_file=registry_expected(path.parent,
    state))`. Гейты и вход арбитража зовут `expect_file=True`: туда
    приходят только с исполненным циклом.

    Умолчание `False` оставляет прежнее поведение (совместимость
    подписи `load_registry(path)`) и держит положительный контроль:
    действительно новый прогон, снимок старта и начало нового круга
    читают пустой реестр, как и прежде."""
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except FileNotFoundError:
        if expect_file:
            raise RegistryMissing(
                f"реестр отсутствует после исполненного цикла: {p}"
            ) from None
        return {}                      # только эта совместимость
    except OSError as e:
        raise RegistryUnavailable(
            f"реестр находок {p.name}: реестр временно недоступен — "
            f"путь есть, а прочитать его как файл не удалось") from e
    try:
        raw = json.loads(text)
    except ValueError as e:
        raise ExchangeError(f"реестр находок {p.name}: файл не читается "
                            f"как JSON: {e}") from e
    # ИНТЕГРАЦИЯ A07 × A09 (решение аудитора 12.09.2026,
    # DECISION-A07-A09-INTEGRATION-LAW): порядок на общей голове —
    # единый загрузчик и проверка формы (A07) → миграция чтения
    # `normalize_registry` (A07-F3: унаследованная техническая
    # отбраковка возвращается в живые, прежний номер уходит в
    # `legacy_code_closure_round`) → дозревание §12.8
    # (`mature_legacy_code_rejections`, A09: та же запись становится
    # тупиком с кодовой причиной и получает путь к арбитру) → и только
    # потом расчёт живых находок, вердикта цикла и споров. Второго
    # загрузчика и второго предиката закрытости нет: судья закрытости —
    # одна нормализация, дозревание лишь читает её следы
    # (`normalized=True`). Чтение файл не переписывает; повторное
    # чтение и повторное дозревание идемпотентны.
    return mature_legacy_code_rejections(
        normalize_registry(
            validate_registry_form(raw, f"реестр находок {p.name}")),
        normalized=True)


def registry_update(registry: dict, round_no: int, pack: dict,
                    resp: dict, cycle: int = 1,
                    patch_rejected: list | None = None,
                    executed: set | None = None) -> list[str]:
    """Проводка обмена по реестру находок; возвращает нарушения
    жизненного цикла. Правила:

    - новое замечание открывает находку;
    - ответ переводит её в «принято»/«отклонено» (ЧАСТИЧНО — принято);
    - отклонённая находка, ПОВТОРЕННАЯ аудитором в следующем обмене
      (то же замечание по тому же адресу), становится «тупик» — решение
      владельца;
    - сохранённая живая Б/К-находка в состоянии «отклонено» без
      повтора в следующем аудите тоже передаётся арбитру: молчание
      не разрешает спор. Это процедурный тупик с неизвестным исходом,
      НЕ признание дефекта и НЕ закрытие; новые отклонения текущего
      обмена не дозревают в том же обмене;
    - закрывает находку только аудитор: отсутствие замечания по
      исправленной находке в СЛЕДУЮЩЕМ аудите переводит «исправлено» →
      «закрыто» (встречная проверка состоялась);
    - живой круг полноты run-0002 (ночь 30→31.08): вердикт ПРИНЯТО
      при ОТБРАКОВАННОМ гейтом патче — правка НЕ встала; такая
      находка получает состояние «патч отбракован» (не «исправлено»)
      и молчанием аудитора НЕ закрывается — иначе живой дефект
      закрывался без правки;
    - A07-F1 (находка аудитора 12.09.2026): вердикт ПРИНЯТО/ЧАСТИЧНО
      БЕЗ ИСПОЛНЕННОЙ правки — пустое обещание, а не исправление.
      `executed` — множество id замечаний, чья заплата действительно
      применилась в этом обмене (его даёт `_apply_patches` через
      `executed_out`): принятый ответ вне него получает то же живое
      состояние «патч отбракован» с причиной. Это ВТОРОЙ, независимый
      замок: первый — отбраковка `принято без исполненной правки`,
      которую пишет `_apply_patches` в patch-rejections.json (по ней
      же повторная проводка гейта получает то же состояние).
      `executed=None` — прежнее поведение для вызовов, которые
      исполнения не знают (повторная проводка гейта, старые вызовы):
      там судьёй остаётся только `patch_rejected`."""
    problems: list[str] = []
    findings = registry.setdefault("findings", [])
    rejected_patch_ids = {rj.get("answer")
                          for rj in (patch_rejected or [])
                          if isinstance(rj, dict)}
    rejected_patch_reason = {
        rj.get("answer"): "; ".join(rj.get("reasons") or [])
        for rj in (patch_rejected or []) if isinstance(rj, dict)}
    if executed is not None:
        for a in resp.get("answers", []):
            if not isinstance(a, dict) \
                    or a.get("verdict") not in ("ПРИНЯТО", "ЧАСТИЧНО") \
                    or a.get("remark") in executed:
                continue
            rejected_patch_ids.add(a.get("remark"))
            rejected_patch_reason.setdefault(a.get("remark"),
                                             EMPTY_PROMISE_REASON)

    def _key(rm: dict) -> str:
        # Ключ — каноническая строка JSON: она хэшируема для словарей,
        # байт-в-байт переживает запись на диск и повторную проводку
        # (кортеж внутри списка после JSON становился списком, и гейт
        # ловил ложное «не сходится» — первый живой цикл пилотной
        # линии).
        return remark_key(rm)

    new_keys = {_key(rm) for rm in pack.get("remarks", [])}
    # Только живые Б/К на ВХОДЕ обмена; тот же закон закрытости, что
    # у панели и гейта. Решённый арбитром ключ гасит и старое эхо.
    pending_blockers = {(f.get("id"), _normalize_key(f.get("key", "")))
                        for f in registry_blockers(registry)
                        if f.get("state") == "отклонено"}
    rejected_keys = {}
    partial_keys = {}
    for f in findings:
        key = f.get("key", "")
        if f["state"] == "исправлено":
            if key in new_keys:
                # Аудитор повторил находку — исправление НЕ принято.
                f["state"] = "открыто"
            else:
                # Встречная проверка состоялась: закрывает аудитор
                # отсутствием замечания, не обработчик.
                f["state"] = "закрыто"
                f["closed_round"] = round_no
        elif f["state"] == "патч отбракован":
            if key in new_keys:
                f["state"] = "открыто"   # повтор — снова в работу
            # без повтора состояние СОХРАНЯЕТСЯ: правка не встала,
            # закрыть молчанием нельзя (листинг незавершённого несёт
            # её аудитору каждый круг).
        elif f["state"] == "отклонено":
            rejected_keys[key] = f
            if key not in new_keys and (
                    f.get("id"), _normalize_key(key)) in pending_blockers:
                # Точный повтор ниже сохраняет прежний вид «повтор».
                # Здесь нет нового довода аудитора и нет решения по
                # существу: неизменённый спор получает путь к арбитру.
                f["state"] = "тупик"
                f["deadlock_kind"] = "неразрешённое отклонение"
                f["deadlock_reason"] = (
                    "Отклонённая Б/К-находка осталась живой после "
                    "следующего аудита без точного повтора. Молчание "
                    "не закрывает спор; исход спора не установлен, "
                    "дефект не признан. Требуется решение арбитра "
                    "по источнику.")
        if f.get("partial"):
            partial_keys[key] = f

    bad_answers = [a for a in resp.get("answers", [])
                   if not isinstance(a, dict)]
    for a in bad_answers:
        problems.append(f"ответ обработчика не объект: {repr(a)[:60]}")
    answers = {a.get("remark"): a for a in resp.get("answers", [])
               if isinstance(a, dict)}
    live_by_key = {f.get("key"): f for f in findings
                   if f.get("state") in ("открыто", "патч отбракован")}
    for rm in pack.get("remarks", []):
        key = _key(rm)
        prior = rejected_keys.get(key)
        if prior is not None:
            # Отклонено и повторено — тупик, решение за владельцем.
            prior["state"] = "тупик"
            prior["deadlock_kind"] = "повтор"
            continue
        a = answers.get(rm.get("id")) or {}
        verdict = a.get("verdict")
        # Один ключ — одна живая находка (проверка плана №18): повтор
        # замечания ведёт ТУ ЖЕ запись, а не рождает вторую, которая
        # закрывается, пока первая остаётся «открытой» навсегда.
        alive = live_by_key.get(key)
        if alive is not None:
            new_state = ("исправлено" if verdict in ("ПРИНЯТО", "ЧАСТИЧНО")
                         else "отклонено" if verdict == "ОТКЛОНЕНО" else "открыто")
            if new_state == "исправлено" and rm.get("id") in rejected_patch_ids:
                new_state = "патч отбракован"
                alive["patch_reason"] = rejected_patch_reason.get(rm.get("id"))
            alive["state"] = new_state
            alive["basis"] = a.get("basis") or ""
            alive["partial"] = verdict == "ЧАСТИЧНО"
            alive["repeated_round"] = round_no
            continue
        # АЦ-4/В2: второе «ЧАСТИЧНО» по той же находке — хвост не
        # сходится, спор дозревает до арбитра.
        prior_partial = partial_keys.get(key)
        if verdict == "ЧАСТИЧНО" and prior_partial is not None:
            prior_partial["state"] = "тупик"
            prior_partial["deadlock_kind"] = "частично"
            continue
        state = ("исправлено" if verdict in ("ПРИНЯТО", "ЧАСТИЧНО")
                 else "отклонено" if verdict == "ОТКЛОНЕНО"
                 else "открыто")
        patch_reason = None
        if state == "исправлено" and rm.get("id") \
                in rejected_patch_ids:
            state = "патч отбракован"
            patch_reason = rejected_patch_reason.get(rm.get("id"))
        # Пространство имён мегакруга: перенесённый реестр несёт
        # находки прежних циклов, а нумерация R{круг}-… каждого цикла
        # начинается заново — без префикса id второго круга совпадал
        # с чужим id первого (живой Лайт run-0039, 2026-08-23).
        prefix = f"C{cycle}-" if cycle > 1 else ""
        findings.append({"id": f"{prefix}R{round_no}-{rm.get('id')}",
                         "opened_round": round_no,
                         "severity": rm.get("severity"),
                         "key": key, "state": state,
                         # АЦ-4/Б1: суть и основание — аудитору
                         # следующего раунда нужен контекст отклонения.
                         "text": rm.get("text") or "",
                         "basis": a.get("basis") or "",
                         "partial": verdict == "ЧАСТИЧНО",
                         **({"patch_reason": patch_reason}
                            if patch_reason else {}),
                         "closed_round": None})
    # Ошибка формы (A07): состояние вне закрытого перечня STATES —
    # отказ словами, а не молчаливая запись (ловит и перенесённый
    # реестр с чужим состоянием, и правку кода мимо перечня).
    foreign = sorted({str(f.get("state")) for f in findings
                      if f.get("state") not in STATES})
    if foreign:
        raise ExchangeError("реестр находок: состояние вне перечня "
                            "STATES: " + ", ".join(foreign))
    return problems


def registry_post_round(registry: dict, accepted: set,
                        old_doc: dict, new_doc: dict) -> None:
    """Пост-раундовые мутации реестра, общие для цикла и повторной
    проводки гейта (АЦ-4): перенос находок на строки-преемники,
    счётчики правок и дозревание осцилляций до тупика."""
    remap_orphan_findings(registry, old_doc, new_doc)
    touch = registry.setdefault("touch", {})
    # Обход по отсортированному перечню: множество обходится в порядке
    # хеша процесса (PYTHONHASHSEED), и порядок ключей `touch` в
    # registry.json различался бы между перезапусками сервера — ломая
    # байтовую сверку повтора (седьмое неавтор-ревью A07, остаток b2).
    for t in sorted(accepted, key=str):
        if t != "+":
            touch[t] = touch.get(t, 0) + 1
    for f in registry.get("findings", []):
        # A07-F1 (закон следа, четвёртое неавтор-ревью): «патч
        # отбракован» — такая же ЖИВАЯ находка правимой строки, как
        # «открыто»/«исправлено». Без неё обмен, где обработчик третий
        # круг подряд несёт заплату-пустышку на ту же строку, вечно
        # висел бы на «патч отбракован» и до арбитра не доходил:
        # прежде такой круг созревал в осцилляцию только потому, что
        # пустая заплата числилась исполненной.
        if f.get("state") in ("открыто", "отклонено", "исправлено",
                              "патч отбракован"):
            try:
                rule_id = (json.loads(f.get("key") or "[]")
                           + [None, None])[1]
            except ValueError:
                rule_id = None
            if rule_id and touch.get(rule_id, 0) >= 3:
                f["state"] = "тупик"
                f["deadlock_kind"] = "осцилляция"


def remap_orphan_findings(registry: dict, old_doc: dict,
                          new_doc: dict) -> int:
    """АЦ-4/А3: смена id строки не рвёт историю находки. Находки
    строк, исчезнувших из свода, переносятся на строку-преемника с
    тем же набором источников (sid+якорь) — иначе счётчик «отклонено
    и повторено» обнулялся и тупики не зрели. Возвращает число
    переносов."""
    new_ids = {r.get("id") for r in new_doc.get("rules", [])}
    old_rules = {r.get("id"): r for r in old_doc.get("rules", [])}

    def sig(rule) -> tuple:
        return tuple(sorted((ref.get("sid"), ref.get("anchor"))
                            for ref in (rule or {}).get("sources", [])))

    succ_by_sig: dict = {}
    for r in new_doc.get("rules", []):
        if r.get("id") not in old_rules:
            succ_by_sig.setdefault(sig(r), r.get("id"))
    moved = 0
    for f in registry.get("findings", []):
        try:
            parts = json.loads(f.get("key") or "[]")
        except ValueError:
            continue
        if len(parts) < 2 or not parts[1] or parts[1] in new_ids:
            continue
        succ = succ_by_sig.get(sig(old_rules.get(parts[1])))
        if succ:
            parts[1] = succ
            f["key"] = json.dumps(parts, ensure_ascii=False)
            f["remapped"] = True
            moved += 1
    return moved


def check_diff_only(old_doc: dict, new_doc: dict,
                    accepted_targets: set[str]) -> list[str]:
    """Diff-only: новая версия модели меняет ТОЛЬКО строки и вопросы из
    принятых замечаний; новые строки допустимы только при принятых
    «пропусках» (маркируются целью «+»). Правка вне диффа запрещена."""
    problems: list[str] = []
    old_rules = {r["id"]: r for r in old_doc.get("rules", [])}
    new_rules = {r["id"]: r for r in new_doc.get("rules", [])}
    for rid, r in new_rules.items():
        if rid not in old_rules:
            if "+" not in accepted_targets:
                problems.append(f"{rid}: новая строка без принятого "
                                f"замечания класса «пропуск»")
        elif r != old_rules[rid] and rid not in accepted_targets:
            problems.append(f"{rid}: строка изменена вне перечня "
                            f"принятых замечаний")
    for rid in old_rules:
        if rid not in new_rules and rid not in accepted_targets:
            problems.append(f"{rid}: строка удалена вне перечня "
                            f"принятых замечаний")
    return problems


def _question_targets(q) -> tuple:
    """Цели вопроса анкеты: строки свода и якоря источника. Порядок не
    значим — добор ссылок судится множествами."""
    if not isinstance(q, dict):
        return ()
    return (tuple(sorted(str(x) for x in (q.get("rule_refs") or []))),
            _question_source_keys(q.get("source_refs")),
            _question_source_keys(q.get("source_refs_technical")))


def _question_source_keys(refs) -> tuple:
    return tuple(sorted(json.dumps(s, ensure_ascii=False, sort_keys=True)
                        for s in (refs or []) if isinstance(s, dict)))


def _question_patch_trace(before, after, patch) -> bool:
    if not isinstance(before, dict) or not isinstance(after, dict):
        return False
    from cdpm import question_editions
    if question_editions.problems(after):
        return False
    changed = False
    for field, key in (("rule_refs", "add_rule_refs"),
                       ("source_refs", "add_source_refs"),
                       ("source_refs_technical", "add_source_refs_technical")):
        additions = patch.get(key) or []
        values = (before.get(field) or [], after.get(field) or [], additions)
        if any(not isinstance(refs, list) for refs in values):
            return False
        item_type = str if field == "rule_refs" else dict
        if any(not isinstance(ref, item_type) for refs in values for ref in refs):
            return False
        encode = (lambda refs: set(refs or [])) if field == "rule_refs" \
            else (lambda refs: set(_question_source_keys(refs)))
        try:
            old, new, wanted = encode(before.get(field)), encode(after.get(field)), encode(additions)
        except (TypeError, ValueError):
            return False
        if not old <= new or not wanted <= new:
            return False
        changed = changed or bool((new - old) & wanted)
    return changed


def executed_by_trace(old_doc: dict, new_doc: dict, answers: list,
                      skip: set | None = None) -> set:
    """ЗАКОН СЛЕДА (A07-F1, четвёртое неавтор-ревью 12.09.2026):
    исполнен тот принятый ответ, чья заявленная заплата оставила СЛЕД
    в новой версии свода. Форма заплаты исполнением НЕ является —
    судится разница версий, тем же сравнением строк, что у
    `check_diff_only`:

    - заплата строки (`patch`, rule_id ≠ «+» и строка в прежней
      версии есть): строка rid новой версии отличается от прежней
      (снятие — строка ушла в OUT либо исчезла: тоже отличие);
    - добавление (`patch` с «+» либо с id, которого в прежней версии
      нет: класс «пропуск» получает id от кода): появилась новая
      строка. Каждое заявленное добавление забирает из пула
      добавленных одну строку — три обещания «добавлю» при одной
      добавленной строке исполнены не все;
    - заплата вида (`kind_patch`): вид строки сменился;
    - заплата вопроса (`question_patch`): цели вопроса
      (rule_refs / source_refs) сменились;
    - «выбор чтения», законно ставший вопросом анкеты
      (`converted_to_question`): вопрос появился, добрал цели либо
      заблокировал строку-носитель. Заплата такого ответа НЕ
      применяется — по ней след и не ищется.

    `skip` — ответы, отбракованные по другой причине: смешанный ответ
    (заплата встала, заплата вида отбракована) исключается целиком,
    как и прежде. Закон один у цикла (`_apply_patches`) и у повторной
    проводки гейта: иначе подчищенный patch-rejections.json возвращал
    бы «исполнение» по одному лишь наличию формы."""
    old_rules = {r.get("id"): r for r in old_doc.get("rules", []) or []
                 if isinstance(r, dict)}
    new_rules = {r.get("id"): r for r in new_doc.get("rules", []) or []
                 if isinstance(r, dict)}
    old_q = {q.get("id"): q for q in old_doc.get("questions", []) or []
             if isinstance(q, dict)}
    new_q = {q.get("id"): q for q in new_doc.get("questions", []) or []
             if isinstance(q, dict)}
    pool = [rid for rid in new_rules if rid not in old_rules]
    skip = skip or set()
    executed: set = set()
    for a in answers:
        if not isinstance(a, dict) \
                or a.get("verdict") not in ("ПРИНЯТО", "ЧАСТИЧНО") \
                or a.get("remark") in skip:
            continue
        traced = False
        converted = a.get("converted_to_question")
        converted = converted if isinstance(converted, str) else None
        patch = a.get("patch")
        if isinstance(patch, dict) and not converted:
            # Идентификатор цели — недоверенный вывод модели: не строка
            # (и не пропуск) следом не становится НИ ПРИ КАКОМ исходе и
            # строки из пула добавленных не занимает; цикл такую
            # заплату отбраковывает по форме.
            rid = patch.get("rule_id")
            if isinstance(rid, str) or rid is None:
                if rid is not None and rid != "+" and rid in old_rules:
                    traced = new_rules.get(rid) != old_rules[rid]
                else:
                    # Строку-новинку именует КОД (стабильный id по
                    # якорю): заявленный id с новым может не совпасть —
                    # след ищется в пуле добавленных, по одной строке
                    # на обещание.
                    take = rid if rid in pool \
                        else (pool[0] if pool else None)
                    if take is not None:
                        pool.remove(take)
                        traced = True
        kp = a.get("kind_patch")
        if not traced and isinstance(kp, dict):
            rid = kp.get("rule_id")
            traced = isinstance(rid, str) \
                and (new_rules.get(rid) or {}).get("kind") \
                != (old_rules.get(rid) or {}).get("kind")
        qp = a.get("question_patch")
        if not traced and isinstance(qp, dict):
            qid = qp.get("question_id")
            traced = isinstance(qid, str) and _question_patch_trace(
                old_q.get(qid), new_q.get(qid), qp)
            if not traced and isinstance(qid, str) and qid in old_q:
                from cdpm import question_editions
                for successor in new_q.values():
                    if successor.get("id") in old_q or successor.get("edition_of") != qid:
                        continue
                    try:
                        question_editions.lineage_root(new_doc, successor)
                        wanted = question_editions.targets(old_q[qid]) | set(
                            qp.get("add_rule_refs") or [])
                        traced = question_editions.targets(successor) == wanted
                        expected_sources = list(old_q[qid].get("source_refs") or [])
                        for source in qp.get("add_source_refs") or []:
                            if source not in expected_sources:
                                expected_sources.append(source)
                        traced = traced and _question_source_keys(successor.get("source_refs")) \
                            == _question_source_keys(expected_sources)
                        traced = traced and _question_patch_trace(old_q[qid], successor, qp)
                    except (question_editions.EditionRefusal, TypeError):
                        traced = False
                    if traced:
                        break
        if not traced and converted and converted in new_q:
            q = new_q[converted]
            traced = converted not in old_q \
                or _question_targets(q) != _question_targets(old_q[converted])
            if not traced:
                # Вопрос-дубль переиспользован: след — блокировка
                # строки-носителя (замок 4П «определённость»).
                traced = any(
                    converted in ((new_rules.get(rid) or {})
                                  .get("blockers") or [])
                    and converted not in ((old_rules.get(rid) or {})
                                          .get("blockers") or [])
                    for rid in (q.get("rule_refs") or []))
        if traced:
            executed.add(a.get("remark"))
    return executed


def no_trace_only(patch_rejected: list | None) -> set:
    """ОДИН ЗАКОН ЦЕЛЕЙ (A07-F1, пятое неавтор-ревью 12.09.2026,
    находка 1) — ЧТЕНИЕ закона по записанным причинам.

    A07-R1 (12.09.2026): судьёй повторной проводки эта функция больше
    не служит — гейт получает цели от самой проводки круга
    (`apply_round_pure` → `_apply_patches`, поля `touch_targets`), а не
    выводит их из текста причин в patch-rejections.json. Закон она
    описывает прежний и остаётся читателем записанных отбраковок (в
    т. ч. для разбора старых каталогов и для проверок этого закона).

    Ответы, ВСЕ причины отбраковки которых — «заплата без
    следа». Заплата такого ответа ПРИМЕНИЛАСЬ (строку она адресует, и
    цикл засчитал ей касание строки) — она лишь ничего не изменила.
    Значит, и повторная проводка гейта обязана считать её цель
    касанием: иначе «патч отбракован» зреет в тупик «осцилляция» у
    цикла и не зреет у реплея — красный гейт на честном каталоге без
    вины обработчика. Ответ с ЛЮБОЙ иной причиной (форма, контракт,
    чужой якорь, откат) целью не считается ни там, ни там: его заплата
    не встала и строку не трогала. Исполнением ни один из них не
    становится — исполнение судит `executed_by_trace` по ПОЛНОМУ
    перечню отбракованных."""
    reasons_by_answer: dict = {}
    for rj in patch_rejected or []:
        if not isinstance(rj, dict):
            continue
        reasons_by_answer.setdefault(rj.get("answer"), []).extend(
            rj.get("reasons") or [])
    return {aid for aid, reasons in reasons_by_answer.items()
            if reasons and all(r == NO_TRACE_REASON for r in reasons)}


def check_regress_tokens(new_doc: dict, tokens: list[dict]) -> list[str]:
    """Регресс-токены: исправление каждой закрытой находки живо в
    текущей версии — контрольная подстрока присутствует в названной
    строке (откат старых фиксов ловится машинно)."""
    problems: list[str] = []
    rules = {r["id"]: r for r in new_doc.get("rules", [])}
    for t in tokens:
        rule = rules.get(t.get("rule"))
        if rule is None:
            problems.append(f"регресс-токен {t.get('id')}: строка "
                            f"{t.get('rule')!r} исчезла из свода")
            continue
        hay = rule.get("statement", "") + " " + rule.get("note", "")
        if t.get("must_contain") and t["must_contain"] not in hay:
            problems.append(f"регресс-токен {t.get('id')}: исправление "
                            f"«{t['must_contain'][:60]}» откатилось в "
                            f"{t.get('rule')}")
    return problems


