#: Каталог ПРЕЖНЕГО цикла того же прогона: «<обмен>-rev-<ревизия>».
#: Панель пишет ревизию с ведущими нулями (exchange-rev-001),
#: тестовый перенос — без них; закон один: число после «-rev-».
_EXCHANGE_REV_RE = re.compile(r"-rev-(\d+)$")


#: Метка обрыва истории свода: маленький файл, который панель кладёт
#: в архив ПЕРЕизвлечения (`webui._archive_exchange_for_reextract`).
#: Архив мегакруга (`_archive_finished_exchange`) её не несёт.
HISTORY_BREAK_FILE = "history-break.json"

#: Слова метки — человек, открывший архив, читает намерение сам.
HISTORY_BREAK_NOTE = (
    "архив ПРЕЖНЕГО свода: свод выпускается заново, реестр в новый "
    "цикл не переносится — история спора здесь оборвана, содержанием "
    "споров нового свода этот архив не является")


def _same_dispute_history(arch: Path, finding: dict) -> bool:
    """Архив «<обмен>-rev-NNN» принадлежит истории ЭТОГО спора?

    ЗАКОН (пятое неавтор-ревью A09, критическая находка): спор
    судится только по содержанию СВОЕЙ истории. Каталог с таким
    именем рождают ДВА разных события, и различать их обязан код:

    - мегакруг (`webui._archive_finished_exchange`) — новый цикл ТОГО
      ЖЕ свода: реестр переносится в новый цикл, спор живёт дальше с
      тем же идентификатором, а его содержание остаётся в архиве. Это
      история спора;
    - ПЕРЕизвлечение (`webui._archive_exchange_for_reextract`) — свод
      выпускается ЗАНОВО: реестр намеренно НЕ переносится («новый
      свод начинает историю с нуля», живой урок run-0001 — старые
      токены судили новый свод), а архив хранит обмены ЧУЖОГО свода.
      Историей спора он не является.

    По ключу замечания архивы неразличимы: ключ строится от якоря
    источника, и у нового свода он тот же — потому досье и тянуло из
    чужого свода терминальную отбраковку замком кода, а арбитр с
    владельцем судили по данным, которых этот свод не видел (§1.3),
    при реестре, говорящем «повтор без замка» (§1.1).

    Различие — по РЕЕСТРУ архива: история непрерывна там, где архив
    знает ту же находку по ИДЕНТИЧНОСТИ — идентификатор И ключ, а не
    один ключ. Реестр лежит в архиве у ОБЕИХ архиваций; разнится
    его СУДЬБА: мегакруг переносит реестр в новый цикл (спор живёт
    дальше с тем же идентификатором — архив знает его), а
    переизвлечение намеренно не переносит (новый свод заводит свои
    находки со своими идентификаторами — архив прежнего свода их не
    знает). Поэтому закон действует и на архивах, созданных ДО этой
    правки: метки у них нет, а реестр есть. Метка же делает
    намерение явным и читаемым человеком.

    Fail-closed: архив без реестра, с нечитаемым реестром, с чужим
    реестром (находки нет) или с меткой обрыва — не история этого
    спора. Находка без идентификатора или без ключа истории не
    имеет вовсе: сопоставлять нечем."""
    if (arch / HISTORY_BREAK_FILE).is_file():
        return False
    fid = finding.get("id")
    key = finding.get("key", "")
    if not fid or not key:
        return False
    key = _normalize_key(key)
    reg = _soft_json(arch / "registry.json", None)
    if not isinstance(reg, dict):
        return False
    for f in (reg.get("findings") or []):
        if not isinstance(f, dict):
            continue
        if f.get("id") == fid \
                and _normalize_key(f.get("key", "")) == key:
            return True
    return False


def archived_exchange_dirs(exchange_dir: Path,
                           finding: dict | None = None) -> list[Path]:
    """Каталоги ПРЕЖНИХ циклов того же прогона — по возрастанию
    ревизии, детерминированно.

    Мегакруг уносит ВЕСЬ каталог обмена в «<обмен>-rev-NNN»
    (`webui._archive_finished_exchange`), перенося в новый цикл лишь
    реестр и регресс-токены: содержание спора — замечание аудитора,
    его доказательство, предложение и основания отклонений
    обработчика — остаётся в архиве. Поиск ограничен каталогом
    прогона (родителем каталога обмена): ни диска, ни соседних
    прогонов.

    Порядок — по ЧИСЛУ ревизии, а не по имени и не по порядку
    файловой системы: «-rev-10» старше «-rev-2», а os.listdir порядка
    не обещает — иначе «последнее по времени содержание» зависело бы
    от машины.

    При переданной находке остаются только архивы ЕЁ истории
    (`_same_dispute_history`): архив переизвлечения хранит обмены
    ЧУЖОГО свода и содержанием этого спора не является. Без находки
    возвращается сам перечень каталогов (кто спрашивает «какие архивы
    есть», тот не судит спор)."""
    parent = exchange_dir.parent
    rows: list[tuple[int, str, Path]] = []
    if parent.is_dir():
        for p in parent.glob(exchange_dir.name + "-rev-*"):
            mt = _EXCHANGE_REV_RE.search(p.name)
            if mt is None or not p.is_dir():
                continue
            rows.append((int(mt.group(1)), p.name, p))
    rows.sort(key=lambda row: (row[0], row[1]))
    dirs = [p for _, _, p in rows]
    if finding is None:
        return dirs
    return [p for p in dirs if _same_dispute_history(p, finding)]


def _soft_json(path: Path, default):
    """Чтение НЕОБЯЗАТЕЛЬНОГО носителя содержания (архив прежнего
    цикла, файл отбраковок): каталога может не быть, он может быть
    неполным (цикл остановлен посреди круга) или нечитаемым. Это не
    исключение — это «содержания здесь нет»; отсутствие содержания
    судится дальше законом пустого досье (fail-closed)."""
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


#: Носители, без которых круг судить нечем: замечания аудитора и
#: ответ обработчика. Строгая ветвь читает ОБА, а писатель кладёт их
#: ПО ОЧЕРЕДИ — `remarks.json` до опроса обработчика, `response.json`
#: после, — поэтому «круг завершён» решает НАБОР, а не первый файл:
#: цикл, убитый между записями, оставляет круг наполовину.
_ROUND_CONTENT_FILES = ("remarks.json", "response.json")


def _dispute_round_dirs(exchange_dir: Path,
                        finding: dict) -> list[tuple[Path, bool]]:
    """Круги обмена, где может лежать содержание ЭТОГО спора, в
    порядке ВРЕМЕНИ: сначала архивы прежних циклов СВОЕЙ истории (по
    возрастанию ревизии), последним — текущий цикл. Второй член пары
    — «это архив»: архив читается мягко, текущий цикл — как прежде,
    строго.

    Архивы отбираются по истории спора, а не по одному имени
    каталога: переизвлечение кладёт под тем же именем обмены ЧУЖОГО
    свода (`_same_dispute_history`).

    НЕЗАВЕРШЁННЫЙ круг ТЕКУЩЕГО цикла пропускается: убитый цикл
    оставляет каталог `round-NN` без обязательных для суда носителей
    (`_ROUND_CONTENT_FILES`), и строгое чтение роняло сборку досье (а
    с нею и гейт арбитража) трассой `FileNotFoundError`. Смерть на
    стадии АУДИТОРА оставляет один `audit-progress.json`, смерть на
    стадии ОБРАБОТЧИКА — `remarks.json` без `response.json`; круг
    незавершён в обоих случаях, и пропускаются оба (шестая правка
    A09: пропуск смотрел только первый носитель, а строгая ветвь
    читала оба — круг, убитый на опросе обработчика, по-прежнему
    ронял трассой). Такой круг и для самого цикла не начат:
    `run_exchange` при возобновлении аудирует его заново.

    Мягкость — ровно на «файла ЕЩЁ НЕТ»: БИТЫЙ (существующий, но
    нечитаемый) носитель текущего цикла остаётся строгим, как
    прежде, — испорченное содержание не то же самое, что
    ненаписанное."""
    rows: list[tuple[Path, bool]] = []
    for arch in archived_exchange_dirs(exchange_dir, finding):
        rows += [(r, True)
                 for r in sorted((arch / "rounds").glob("round-*"))]
    rows += [(r, False)
             for r in sorted((exchange_dir / "rounds").glob("round-*"))
             if all((r / name).is_file()
                    for name in _ROUND_CONTENT_FILES)]
    return rows


def _dossier_is_empty(remark: dict | None, clause: str,
                      rule: dict | None) -> bool:
    """Досье пусто: нет НИ замечания, ни доказательства, ни
    предложения, ни клаузы источника, ни строки свода — судить нечем.

    Слова запрета кодом досье не наполняют: запрет говорит, почему
    заплата незаконна, но не говорит, о ЧЁМ спор."""
    rm = remark or {}
    if any(str(rm.get(k) or "").strip()
           for k in ("text", "evidence", "proposal")):
        return False
    if str(clause or "").strip() not in ("", "<нет>"):
        return False
    return rule is None


#: Отказ записью по пустому досье — две разные причины, названные
#: словами (четвёртое неавтор-ревью A09): потерянный ключ и
#: ненайденное содержание — беды разные, и лечатся они по-разному.
_EMPTY_DOSSIER_NO_KEY = (
    "у находки нет ключа, а досье спора пусто: замечание не найдено "
    "ни в одном круге обмена — предъявлять арбитру нечего, спор не "
    "судится и не закрывается")
_EMPTY_DOSSIER_NO_CONTENT = (
    "содержания спора не нашлось: судить нечем — замечания нет ни в "
    "кругах этого цикла, ни в архивах прежних циклов своей истории "
    "(<обмен>-rev-NNN), ни в отбраковках запрещённых повторов; "
    "предъявлять арбитру нечего, спор не судится и не закрывается")


def _deadlock_dossier(exchange_dir: Path, finding: dict) -> dict:
    """Досье тупика: замечание аудитора, все основания отклонений
    обработчика по обменам и — для тупика, дозревшего из терминальной
    отбраковки замком кода (§12.8), — сама заплата и слова замка.

    Без последнего арбитр судил бы спор о заплате, которой не видел:
    обработчик ответил «ПРИНЯТО» (оснований отклонения нет вовсе), а
    запрет пришёл от кода. Причина берётся и из записи реестра
    (`code_rejection` — то, что сохранил писатель), и из файлов
    отбраковки раундов (`patch-rejections.json`) — сверка двух
    носителей, а не доверие одному производному полю. Носители
    архивного круга читаются МЯГКО все до одного, включая файл
    отбраковок: неполный или битый архив — «содержания здесь нет», а
    не исключение.

    Досье собирается по СОДЕРЖАНИЮ, где бы оно ни лежало (четвёртое
    неавтор-ревью A09, критическая находка «слепой суд перенесённого
    спора»): круги ТЕКУЩЕГО цикла — не единственный носитель. Живой
    спор переживает границу мегакруга (реестр переносится,
    `reopen_unresolved_disputes` возвращает его тупиком), а каталог с
    кругами уходит в архив — и досье оказывалось пустым ВСЕГДА, хотя
    спор был налицо. Поэтому ищутся:

    - круги архивов прежних циклов СВОЕЙ истории (по возрастанию
      ревизии; последнее по времени содержание выигрывает). Архив
      ПЕРЕизвлечения историей не является: он хранит обмены прежнего
      СВОДА, и судить по ним — судить не то, что видел этот цикл
      (`_same_dispute_history`, пятое неавтор-ревью A09);
    - `audit-rejections.json` — носитель, куда содержание переносится
      штатно: повтор замечания по спору замка кода машинно ЗАПРЕЩЁН
      (§12.8), в `remarks.json` нового мегакруга он не попадает
      вовсе, и отклонённое замечание живёт только здесь. Этот носитель
      — запасной: он не перебивает замечание, дошедшее до круга.

    Поиск — по идентичности спора (ключ замечания), детерминированный
    и ограниченный каталогом прогона."""
    key = finding.get("key", "")
    remark = None
    banned_remark = None
    rejections: list[str] = []
    code_rejections: list[dict] = []
    for rdir, archived in _dispute_round_dirs(exchange_dir, finding):
        if archived:
            pack = _soft_json(rdir / "remarks.json", {})
            resp = _soft_json(rdir / "response.json", {})
            if not isinstance(pack, dict):
                pack = {}
            if not isinstance(resp, dict):
                resp = {}
        else:
            pack = json.loads((rdir / "remarks.json")
                              .read_text(encoding="utf-8"))
            resp = json.loads((rdir / "response.json")
                              .read_text(encoding="utf-8"))
        # Запрещённый повтор: содержание спора в этом круге — здесь.
        for row in (_soft_json(rdir / "audit-rejections.json", []) or []):
            if not isinstance(row, dict):
                continue
            rm_b = row.get("remark")
            if isinstance(rm_b, dict) and remark_key(rm_b) == key:
                banned_remark = rm_b
        answers = {a.get("remark"): a
                   for a in resp.get("answers", [])
                   if isinstance(a, dict)}
        # Отбраковки читаются тем же законом, что и сам круг: архив
        # — МЯГКО (обрезанный файл прежнего цикла — «содержания
        # здесь нет»), текущий цикл — строго. Прежде обе ветви
        # читались строго, и битый архивный файл ронял досье
        # `JSONDecodeError` вопреки обещанию мягкого чтения архивов
        # (шестая правка A09).
        rej_path = rdir / "patch-rejections.json"
        if archived:
            raw = _soft_json(rej_path, [])
        elif rej_path.is_file():
            raw = json.loads(rej_path.read_text(encoding="utf-8"))
        else:
            raw = []
        if not isinstance(raw, list):
            raw = []
        rejected_rows: list[dict] = [r for r in raw
                                     if isinstance(r, dict)]
        # Терминальность — тем же законом, что у писателя
        # (code_terminal_closures), а не пересказом слов; закон
        # судит раунд целиком, поэтому считается один раз на раунд.
        terminal = code_terminal_closures(rejected_rows, pack)
        for rm in pack.get("remarks", []):
            # Единый ключ находки (АЦ-4/А2): собственная формула досье
            # разошлась с реестром при нормализации ключа — тупик
            # «пропуска» терял замечание и выпадал из арбитража.
            if remark_key(rm) != key:
                continue
            remark = rm
            a = answers.get(rm.get("id")) or {}
            if a.get("verdict") == "ОТКЛОНЕНО":
                rejections.append(a.get("basis", ""))
            for rj in rejected_rows:
                if rj.get("answer") != rm.get("id"):
                    continue
                code_rejections.append({
                    "round": rdir.name,
                    "patch": a.get("patch"),
                    "reasons": [str(r)
                                for r in (rj.get("reasons") or [])],
                    "terminal": key in terminal})
    return {"remark": remark if remark is not None else banned_remark,
            "rejections": rejections,
            "code_rejections": code_rejections,
            # Замечание дошло до арбитра только запасным носителем —
            # запрещённым повтором: честно назвать, откуда содержание.
            "remark_from_ban": remark is None and banned_remark is not None,
            # Слова замка, сохранённые писателем при дозревании.
            "code_rejection": finding.get("code_rejection")}


def _revert_arbiter_trace(base_doc: dict, doc: dict, target: str | None,
                          own_qid: str, reused_qid: str | None) -> None:
    """Снимает след ПРЕЖНЕГО исполнения тупика, возвращённого на
    переарбитрацию (вердикт на тупик один и последний — и след его
    исполнения тоже): строка-цель возвращается к доарбитражной
    редакции, собственный вопрос арбитража этого тупика убирается
    вместе с блокировками строк-носителей, переиспользованный
    вопрос-дубль возвращается к доарбитражной редакции (если он
    существовал до арбитража; вопрос другого тупика того же захода не
    трогается). Пропуск («+») адреса следа не имеет — добавленная
    прежде строка остаётся в модели."""
    old_rules = {r["id"]: r for r in doc.get("rules", [])}
    old_q = {q["id"]: q for q in doc.get("questions", [])}
    if target and target != "+" and target in old_rules:
        base_doc["rules"] = [copy.deepcopy(old_rules[target])
                             if r["id"] == target else r
                             for r in base_doc.get("rules", [])]
    qids = [own_qid]
    if reused_qid and reused_qid in old_q:
        qids.append(reused_qid)
    for qid in qids:
        if qid in old_q:
            base_doc["questions"] = [
                copy.deepcopy(old_q[qid]) if q["id"] == qid else q
                for q in base_doc.get("questions", [])]
        else:
            base_doc["questions"] = [q for q in base_doc.get("questions", [])
                                     if q["id"] != qid]
        for r in base_doc.get("rules", []):
            old = old_rules.get(r["id"])
            if old is None or qid not in (r.get("blockers") or []) \
                    or qid in (old.get("blockers") or []):
                continue
            r["blockers"] = [b for b in r["blockers"] if b != qid]
            if not r["blockers"] and "blockers" not in old:
                r.pop("blockers")


def code_locked_deadlock(finding: dict) -> bool:
    """Тупик, дозревший из ТЕРМИНАЛЬНОЙ отбраковки замком кода (§12.8):
    законной заплаты по нему не существует — ни от обработчика (её уже
    отверг замок), ни от арбитра (арбитр судит спор, а не пишет код).
    Признают ОБА носителя разом: вид тупика и сохранённые слова замка;
    одного производного поля мало — подделанный ярлык без причины
    отправляет находку обычной дорогой, где отсутствие заплаты честно
    станет неисполненным вердиктом."""
    return finding.get("deadlock_kind") == CODE_DEADLOCK_KIND \
        and bool(str(finding.get("code_rejection") or "").strip())


def code_locked_dispute(finding: dict, dossier: dict | None = None
                        ) -> bool:
    """Замок кода запретил заплату по этому спору — по ЛЮБОМУ из
    носителей (ревью A09, находка 1).

    Производные поля реестра (`deadlock_kind`, `code_rejection`) пишет
    тот же арбитраж, чью честность и судят: кто подделал реестр, снимет
    и их — и запрет исчезнет вместе со следом. Третий носитель
    независим от писателя реестра: файлы отбраковки раундов
    (`patch-rejections.json`), терминальность которых судит тот же
    закон `code_terminal_closures`, что судил её в цикле. Достаточно
    любого: спор, чью заплату отверг замок, законной заплаты не имеет —
    сколько бы полей реестра ни стёрли.

    `dossier` — досье тупика (`_deadlock_dossier`); без него судятся
    только поля реестра."""
    if code_locked_deadlock(finding):
        return True
    return any(cr.get("terminal")
               for cr in ((dossier or {}).get("code_rejections") or [])
               if isinstance(cr, dict))


#: Состояния спора, который арбитраж ЕЩЁ разбирает: «тупик» и спор,
#: оставшийся неразрешённым в своём цикле (A09).
ARBITRABLE_STATES = ("тупик", "не разрешено арбитром")


def match_listed_deadlocks(registry: dict | None,
                           listed: list[dict] | None) -> dict:
    """Соответствие «тупик перечня `verdict.json` → запись реестра».

    ОДИН закон сопоставления для суда (`run_arbiter`) и для его
    проверки (гейт арбитража) — ревью A09 №2, находка 6. Сопоставление
    по паре (идентификатор, ключ): перенесённый сквозь мегакруги реестр
    несёт находки ПРЕЖНИХ циклов, а нумерация R{круг}-A{аудитор}-{n}
    там начинается заново — «последний по id побеждает» сверял вердикт
    с ЧУЖОЙ находкой (живой Лайт run-0039, 2026-08-23). Запасной проход
    по одному идентификатору — для перечней БЕЗ ключей (вердикты
    прогонов до АЦ-4); прежде он был только у гейта, и по старому
    `verdict.json` арбитр не судил НИЧЕГО, пока гейт судил находку:
    суд и его проверка расходились в самом предмете.

    Возвращает {id тупика перечня: запись реестра или None} в порядке
    перечня; вход не меняется (значения — сами записи реестра)."""
    findings = [f for f in ((registry or {}).get("findings") or [])
                if isinstance(f, dict)]
    by_pair = {(f.get("id"), f.get("key")): f for f in findings}
    by_id: dict = {}
    for f in findings:
        by_id.setdefault(f.get("id"), f)
    out: dict = {}
    for d in (listed or []):
        if not isinstance(d, dict):
            continue
        fid = d.get("id")
        out[fid] = by_pair.get((fid, d.get("key"))) or by_id.get(fid)
    return out


def code_lock_owner_question(finding: dict, docs: list[dict],
                             reuse: dict | None = None) -> str | None:
    """ОТКРЫТЫЙ вопрос владельцу, которым спор замка кода уже передан
    (§12.8: «менять ли требование кода»). Возвращает id вопроса или
    None.

    Носители id вопроса — по убыванию надёжности: поле находки
    (`arbiter_question` — переживает границу мегакруга), собственный
    вопрос арбитража этого тупика и след переиспользования прежнего
    отчёта (`question_reuse`). `docs` — модели по убыванию свежести:
    открытость судится по САМОЙ СВЕЖЕЙ модели, где вопрос найден, а не
    по любой, где он ещё открыт, — иначе применённый ответ владельца не
    снимал бы щита (доарбитражная версия цикла помнит вопрос
    открытым)."""
    from cdpm import model as m, question_editions as qe
    want = [q for q in (finding.get("arbiter_question"),
                        m.stable_question_id(
                            "2", f"арб-{finding.get('id')}"),
                        (reuse or {}).get(finding.get("id")))
            if isinstance(q, str) and q]
    for qid in want:
        for doc in docs:
            questions = (doc or {}).get("questions", [])
            matches = [x for x in questions
                       if isinstance(x, dict) and x.get("id") == qid]
            if not matches:
                continue
            ids = [x.get("id") for x in questions if isinstance(x, dict)]
            if (len(ids) != len(questions) or any(not isinstance(x, str) for x in ids)
                    or len(set(ids)) != len(ids)):
                return qid        # неоднозначная модель не снимает щита
            q = matches[0]
            if qe.is_superseded(doc, q):
                q = qe.latest(doc, q)
            elif any(x.get("edition_of") == qid for x in questions):
                return qid        # непроверенный преемник не заменяет ответ
            try:
                qe.require_valid(q)
                if "edition" in q or q.get("edition_of"):
                    qe.lineage_root(doc, q)
            except qe.EditionRefusal:
                return qid
            if m.is_open_question(q, doc=doc):
                return q["id"]
            break                 # найден в свежайшей модели и отвечен
    return None


def awaits_owner_answer(finding: dict, dossier: dict | None,
                        docs: list[dict],
                        reuse: dict | None = None) -> str | None:
    """Щит fail-closed (ревью A09 №2, находка 3): спор, по которому
    «аудитор прав» УЖЕ передан владельцу открытым вопросом анкеты,
    арбитру заново НЕ предъявляется — он остаётся живым и блокирующим,
    пока владелец не ответит.

    Без щита следующий заход арбитража переворачивал решение замка кода
    в «обработчик прав» БЕЗ слова владельца: находка закрывалась, а
    вопрос анкеты и блокировка строки-носителя повисали сиротами —
    решение авиакомпании подменялось третьей моделью.

    Три следа разом, иначе спор идёт обычной дорогой: названная причина
    неисполнения при находке, запрет замка кода по любому носителю
    (§12.8) и сам вопрос — открытый. Возвращает id вопроса или None."""
    if not str(finding.get("arbiter_unenforced") or "").strip():
        return None
    if not code_locked_dispute(finding, dossier):
        return None
    return code_lock_owner_question(finding, docs, reuse)


def _enforcement_changed_row(target: str, rows_before: dict,
                             rows_after: dict,
                             new_rule_id: str | None) -> bool:
    """След исполнения в модели — тем же критерием, что у гейта
    арбитража: для пропуска («+») появилась новая строка (по
    регресс-токену заплаты, иначе — любая новая), для строки-цели —
    её редакция после применения отличается от прежней. Заплата,
    тождественная строке, следа не оставляет — исполнением не
    считается (ревью A3.5, 2026-09-04: заплата-пустышка закрывала
    находку, а гейт тот же случай называл нарушением)."""
    if target == "+":
        if new_rule_id is not None:
            return new_rule_id not in rows_before
        return any(rid not in rows_before for rid in rows_after)
    return rows_before.get(target) != rows_after.get(target)


def run_arbiter(kit_dir: Path, exchange_dir: Path, arbiter_llm,
                worker_llm, control=None) -> dict:
    """Арбитраж тупиков цикла третьей независимой моделью.

    ПРЕДМЕТ разбирательства — СПОР, а спор опознаётся ключом замечания
    (A09/X-03, решение ведущего сессии 12.09.2026): находки одного
    ключа — повторы одного и того же спора, и арбитру они
    предъявляются ОДНИМ блоком, а решение применяется ко всем разом.
    Прежде они предъявлялись порознь и получали разные решения — ключ
    считался решённым и цикл приходил к «успеху»: контрпример §1.5
    контракта П0 на уровне спора.

    По каждому тупику — один из трёх вердиктов (решение владельца
    2026-08-18): «обработчик прав» (замечание отклонено окончательно),
    «аудитор прав» (обработчик ОБЯЗАН исполнить — патч без права
    отклонить, через гейт контракта), «в анкету» (спорное чтение —
    вопрос части 2 с развилкой из двух чтений, строка блокируется).
    Состояние находки в реестре — по ФАКТУ исполнения вердикта:
    «аудитор прав» закрывает только принятой заплатой, «в анкету» —
    только созданным/переиспользованным вопросом; неисполненный
    вердикт оставляет «тупик» с причиной (отчёт unenforced), и
    повторный арбитраж судит его заново.

    Спор, по которому решения арбитра НЕ ОДНОЗНАЧНЫ (A09, контракт П0
    §1.3 и §12.2): любой повтор ожидаемого идентификатора после
    повторного запроса — и противоречивые решения, и два одинаковых —
    решением не становится; тупик получает состояние «не разрешено
    арбитром» с причиной словами (`arbiter_unresolved`), перечень
    `unresolved` отчёта, раунд его не закрывает, и через закон живых
    находок (A07) он делает вердикт «успех» невозможным. Такой тупик
    судится заново следующим заходом арбитража того же цикла.

    Тупик, дозревший из ТЕРМИНАЛЬНОЙ отбраковки замком кода (§12.8,
    `deadlock_kind = CODE_DEADLOCK_KIND`), судится теми же тремя
    решениями, но законной заплаты по нему нет: «обработчик прав»
    закрывает спор решением, «в анкету» ставит вопрос обычным путём, а
    «аудитор прав» НЕ порождает заплату кодом — арбитр не обходит
    замок незаконной правкой. Находка остаётся живой («тупик») с
    причиной в `arbiter_unenforced`, строкой в `unenforced` отчёта и
    вопросом анкеты владельцу: менять ли требование кода — решение
    авиакомпании и владельца, не моделей.

    Пока этот вопрос ОТКРЫТ, спор арбитру заново не предъявляется (щит
    fail-closed, ревью A09 №2): исход у него свой — перечень
    `awaiting_owner` отчёта, состояние реестра остаётся живым
    («тупик»), а «успех» цикла невозможен. Иначе следующий заход
    перевернул бы решение без слова владельца, оставив вопрос и
    блокировку строки сиротами.
    Итог: новая версия модели, обновлённый реестр, отчёт арбитража."""
    from cdpm import extract as extract_mod
    from cdpm import llm as llm_mod
    from cdpm import model as m
    from cdpm import render

    # A07-R5: ВХОД АРБИТРАЖА. Арбитраж возможен только после
    # исполненного цикла (его вердикт читается строкой ниже) — реестр
    # обязан быть. Пустой реестр здесь означал бы «тупиков нет» и
    # молча завершал арбитраж ничем.
    registry = load_registry(exchange_dir / "registry.json",
                             expect_file=True)
    # В2-3: реестр, писанный прежним кодом, мигрирует и здесь — иначе
    # досье тупика со старым ключом не находит замечание и арбитр
    # судит по пустому блоку (состязательная проверка 2026-08-21).
    normalize_registry_keys(registry)
    verdict_summary = json.loads((exchange_dir / "verdict.json")
                                 .read_text(encoding="utf-8"))
    # Разбирательства этого захода — ТОЛЬКО тупики вердикта СВОЕГО
    # цикла, и закон один для обоих живых состояний спора: «тупик» и
    # «не разрешено арбитром» (A09; ревью A09, находка 3). Реестр
    # переносится сквозь мегакруги, находка чужого цикла отчёту этого
    # цикла не принадлежит, а нумерация R{круг}-A{аудитор}-{n}
    # начинается заново — поэтому сопоставление по паре (id, ключ), тем
    # же законом, каким сопоставляет гейт арбитража. Прежде «тупик»
    # брался из реестра безусловно: арбитр судил спор, которого нет в
    # `verdict.json`, а гейт честно краснел «вердикт по неизвестному
    # тупику» — суд и его проверка расходились в самом предмете.
    # Перенесённый неразрешённый спор попадает в новый `verdict.json`
    # не отсюда, а с порога цикла — `reopen_unresolved_disputes`.
    listed = verdict_summary.get("deadlocks", [])
    normalize_registry_keys({"findings": listed})
    # Сопоставление «тупик перечня → запись реестра» — ОДНОЙ функцией с
    # гейтом арбитража (ревью A09 №2, находка 6): пара (id, ключ), а
    # для перечней без ключей — запасной проход по id. Прежде запасной
    # проход был только у гейта, и по старому `verdict.json` арбитр не
    # судил ничего, пока гейт судил находку.
    entry_of = match_listed_deadlocks(registry, listed)
    deadlocks = [e for e in entry_of.values()
                 if e is not None and e.get("state") in ARBITRABLE_STATES]
    doc = m.load_model(exchange_dir / "versions"
                       / verdict_summary["final_version"])
    m.derive_all_rule_traits(doc, "вход арбитража")   # ярлыки кодом
    kit_entries = extract_mod._load_kit(kit_dir)
    clause_by_key = {(e["sid"], c["anchor"]): c["text"]
                     for e in kit_entries for c in e["clauses"]}
    rules_by_id = {r["id"]: r for r in doc.get("rules", [])}

    dossiers = {f["id"]: _deadlock_dossier(exchange_dir, f)
                for f in deadlocks}
    prev_path = exchange_dir / "arbiter.json"
    prev_report: dict = {}
    if prev_path.is_file():
        prev_report = json.loads(prev_path.read_text(encoding="utf-8"))
    arb_model = exchange_dir / "versions" / "model-arbiter.json"

    # §12.8 + ревью A09 №2, находка 3 — щит fail-closed. Спор замка
    # кода, по которому «аудитор прав» уже передан владельцу ОТКРЫТЫМ
    # вопросом анкеты, второй раз арбитру НЕ предъявляется: он ждёт
    # ответа владельца, оставаясь живым и блокирующим. Прежде следующий
    # заход судил его заново и мог перевернуть решение в «обработчик
    # прав» без слова владельца — находка закрывалась, а вопрос анкеты
    # и блокировка строки-носителя повисали сиротами. Исход такого
    # спора в отчёте свой — перечень `awaiting_owner`.
    q_docs = [doc]
    if arb_model.is_file():
        q_docs.insert(0, m.load_model(arb_model))
    prev_reuse_all = prev_report.get("question_reuse") or {}
    waits_of = {f["id"]: awaits_owner_answer(f, dossiers.get(f["id"]),
                                             q_docs, prev_reuse_all)
                for f in deadlocks}
    # Щит держит СПОР целиком (A09/X-03: спор — это ключ): ждёт ответа
    # владельца одна находка ключа — ждут все, иначе половину спора
    # рассудили бы заново и решения разошлись бы внутри одного ключа.
    waiting_keys: dict = {}
    for f in deadlocks:
        if f.get("key") and waits_of[f["id"]]:
            waiting_keys.setdefault(f["key"], waits_of[f["id"]])
    awaiting: list[dict] = []
    presented: list[dict] = []
    for f in deadlocks:
        waits = waits_of[f["id"]] or waiting_keys.get(f.get("key"))
        if waits is None:
            presented.append(f)
            continue
        awaiting.append({
            "deadlock": f["id"], "question": waits,
            "verdict": "аудитор прав",
            "reason": (f"спор ждёт ответа владельца: вопрос {waits} "
                       f"анкеты открыт — до ответа спор арбитру не "
                       f"предъявляется. "
                       + str(f.get("arbiter_unenforced") or "").strip())})
    deadlocks = presented

    # Частичная переарбитрация (возврат отдельных тупиков на повторный
    # суд при существующем отчёте): база модели — versions/
    # model-arbiter.json, а не доарбитражная версия. Прежде база
    # бралась доарбитражной, и перезапись model-arbiter.json стирала
    # принятые заплаты и созданные вопросы тупиков, не судимых в этом
    # заходе (ревью A3.5, 2026-09-04: гейт краснел «числится
    # исполненным, но строка-цель не изменена»). След исполнения
    # снимается ТОЛЬКО у переарбитрируемых тупиков.
    base_doc = copy.deepcopy(doc)
    if prev_report and deadlocks and arb_model.is_file():
        base_doc = m.load_model(arb_model)
        m.derive_all_rule_traits(base_doc, "вход арбитража")
        prev_reuse = prev_report.get("question_reuse") or {}
        for f in deadlocks:
            rm0 = dossiers[f["id"]]["remark"] or {}
            _revert_arbiter_trace(
                base_doc, doc,
                ((rm0.get("target") or {}).get("rule")) or "+",
                m.stable_question_id("2", f"арб-{f['id']}"),
                prev_reuse.get(f["id"]))
    # A09/X-03 (решение ведущего сессии 12.09.2026, золотой стандарт
    # «спор = ключ»): ПРЕДМЕТ арбитража — спор, а спор опознаётся
    # КЛЮЧОМ замечания, как его уже опознают закон живых находок
    # (`live_findings`, A07) и машинный запрет повтора. Пока спор зрел,
    # каждый повтор открывал отдельную находку — и арбитру эти находки
    # предъявлялись порознь: он давал им РАЗНЫЕ решения («аудитор
    # прав» одной, «обработчик прав» другой), ключ считался решённым,
    # реестр очищался, гейт зеленел — прямой контрпример §1.5
    # контракта П0 («ни одно решение не принимается при наличии
    # противоречащего»). Поэтому блок предъявляется ОДИН на ключ, а
    # решение применяется ко ВСЕМ находкам ключа разом. Формы отчёта и
    # реестра остаются прежними: запись на каждую находку, решение
    # копируется в каждую; перечень тупиков `verdict.json` тоже
    # по-прежнему перечисляет находки.
    groups: list[list[dict]] = []
    group_at: dict[str, int] = {}
    for f in deadlocks:
        gk = f.get("key") or f"\x00id\x00{f['id']}"
        if gk in group_at:
            groups[group_at[gk]].append(f)
        else:
            group_at[gk] = len(groups)
            groups.append([f])
    #: находка → представитель её спора (блок, решение и вопрос общие).
    lead_of = {f["id"]: grp[0]["id"] for grp in groups for f in grp}

    blocks = {}
    #: Спор → причина словами, по которой он арбитру НЕ предъявлялся.
    empty_dossier: dict[str, str] = {}
    for grp in groups:
        f = grp[0]
        d = dossiers[f["id"]]
        rm = d["remark"] or {}
        refs = rm.get("source_refs") or [{}]
        # Якорь замечания бывает в квадратных скобках («[табл.6, …]»)
        # — как у кандидатов извлечения; без нормализации досье теряло
        # клаузу, и арбитр судил по «<нет>» (живой арбитраж пилотной
        # линии 2026-08-18, вердикты R1-A1-092/096 первой попытки).
        anchor = extract_mod._normalize_anchor(refs[0].get("anchor"))
        clause = clause_by_key.get((refs[0].get("sid"), anchor),
                                   "<нет>")
        rule = rules_by_id.get((rm.get("target") or {}).get("rule"))
        # ПУСТОЕ ДОСЬЕ — ОТКАЗ ЗАПИСЬЮ, при ЛЮБОЙ находке (четвёртое
        # неавтор-ревью A09, критическая находка; fail-closed).
        # Прежде отказ держался только на находке БЕЗ КЛЮЧА, а спор С
        # ключом, чьё содержание осталось в кругах ПРЕЖНЕГО цикла,
        # уходил модели блоком «Замечание аудитора: None /
        # Доказательство: None / Предложение: None / Клауза источника
        # [None]: <нет> / Строка свода: <нет>» — арбитр отвечал
        # «обработчик прав», живой блокирующий спор закрывался БЕЗ
        # СОДЕРЖАНИЯ, реестр пустел и цикл приходил к «успеху»:
        # контрпример §1.3 (решение обязано соответствовать исходным
        # данным) и §1.5 контракта П0. Досье теперь ищет содержание и
        # в архивах прежних циклов, и в носителе запрещённых повторов
        # (`_deadlock_dossier`); если и там ничего — модель НЕ зовётся
        # вовсе, причина называется словами, спор остаётся живым.
        if _dossier_is_empty(rm, clause, rule):
            empty_dossier[f["id"]] = (_EMPTY_DOSSIER_NO_KEY
                                      if not f.get("key")
                                      else _EMPTY_DOSSIER_NO_CONTENT)
            continue
        # §12.8: спор, дозревший из отбраковки замком кода, приходит к
        # арбитру с ТОЙ ЖЕ заплатой и теми же словами запрета, что
        # видел цикл: иначе арбитр судил бы вслепую и мог бы велеть
        # написать запрещённое.
        code_words: list[str] = []
        for w in ([str(f.get("code_rejection") or "").strip()]
                  + [r for cr in d["code_rejections"]
                     for r in cr["reasons"]]):
            # Два носителя сверяются, но арбитру одни и те же слова
            # дважды не показываются: писатель кладёт причину раунда
            # внутрь своей формулировки.
            if w and not any(w in seen for seen in code_words):
                code_words.append(w)
        code_patch = next((cr["patch"] for cr in d["code_rejections"]
                           if cr["patch"] is not None), None)
        # Запрет кода показывается, только когда он есть: сообщить о
        # несуществующем запрете значило бы склонить арбитра к исходу,
        # которого спор не содержит.
        code_block = ""
        if code_words:
            code_block = (
                f"Причина запрета кодом: {' | '.join(code_words)}\n")
            if code_patch is not None:
                code_block += (
                    f"Заплата обработчика, отвергнутая кодом: "
                    f"{json.dumps(code_patch, ensure_ascii=False)}\n")
        # Спор один — находок по нему бывает несколько (повторы,
        # дозревшие в отдельные тупики). Арбитр видит их ВСЕ: вид
        # тупика, круг созревания, слова замка и прежнюю
        # неразрешённость, — и знает, что решение будет применено ко
        # всем разом.
        kin_block = ""
        if len(grp) > 1:
            rows = []
            for g in grp:
                bits = [f"вид тупика: "
                        f"{g.get('deadlock_kind') or 'не назван'}"]
                if g.get("deadlock_kind_before_code"):
                    bits.append(f"прежний вид: "
                                f"{g['deadlock_kind_before_code']}")
                if g.get("opened_round") is not None:
                    bits.append(f"открыт в круге {g['opened_round']}")
                if g.get("code_rejected_round") is not None:
                    bits.append(f"замок кода в круге "
                                f"{g['code_rejected_round']}")
                if str(g.get("code_rejection") or "").strip():
                    bits.append(f"слова замка: {g['code_rejection']}")
                if str(g.get("arbiter_unresolved") or "").strip():
                    bits.append(f"прежде не разрешено: "
                                f"{g['arbiter_unresolved']}")
                if str(g.get("deadlock_reason") or "").strip():
                    bits.append(f"причина передачи: {g['deadlock_reason']}")
                rows.append(f"  - [{g['id']}] " + "; ".join(bits))
            kin_block = (
                f"Спор ОДИН (то же замечание по тому же адресу), "
                f"находок по нему {len(grp)} — решение будет применено "
                f"ко ВСЕМ:\n" + "\n".join(rows) + "\n"
                # Родичи названы, чтобы арбитр видел весь спор, — но
                # ответ по родичу решением спора не становится (К-1):
                # предупредить дешевле, чем ловить (закон — ниже, в
                # разборе ответа).
                + f"В ответе назови ОДИН идентификатор — [{f['id']}]: "
                  f"решение, названное по любой другой из этих находок, "
                  f"спор НЕ разрешает.\n")
        blocks[f["id"]] = (
            f"=== Тупик [{f['id']}] · {rm.get('severity')} · "
            f"{rm.get('defect_class')} · вид тупика: "
            f"{f.get('deadlock_kind') or 'не назван'}\n"
            + (f"Причина передачи: {f['deadlock_reason']}\n"
               if f.get("deadlock_reason") else "")
            + kin_block +
            f"Замечание аудитора: {rm.get('text')}\n"
            f"Доказательство аудитора: {rm.get('evidence')}\n"
            f"Предложение аудитора: {rm.get('proposal')}\n"
            f"Основания отклонений обработчика: "
            f"{' | '.join(d['rejections']) or '<нет>'}\n"
            + code_block +
            f"Клауза источника [{refs[0].get('anchor')}]: {clause}\n"
            f"Строка свода: "
            f"{json.dumps(rule, ensure_ascii=False) if rule else '<нет>'}"
        )

    if control:
        control()              # пауза/остановка перед вердиктами (ПС-1)
    verdicts: dict[str, dict] = {}
    #: A09: тупик (и лишний идентификатор ответа) → причина словами.
    unresolved_now: dict[str, str] = {}
    if blocks:
        # Context is not a new dispute/id. Prepending it to a real block keeps
        # the common judge's completeness and duplicate laws unchanged.
        first = next(iter(blocks))
        blocks[first] = _catalog_prompt_context(doc) + "\n\n" + blocks[first]
        # Пакетный сбор решений с повтором, полнотой и законом дубля —
        # общий механизм с внутренним судьёй разработки. Неразрешённое
        # не отбрасывается и не превращается в «первое из двух».
        from cdpm.judge import batch_verdicts
        verdicts, unresolved_now = batch_verdicts(
            arbiter_llm, _PROMPT_ARBITER, blocks, ARBITER_VERDICTS,
            id_field="deadlock")
    # A09/X-03 (третье ревью, К-1): решение, названное по РОДИЧУ спора,
    # — неоднозначность ВСЕГО спора, а не посторонний мусор. Арбитр
    # видит родичей в самом блоке («Спор ОДИН …, находок по нему N:
    # [id] …»), и ответ по родичу — ответ по ЭТОМУ спору, только
    # названный не тем идентификатором. Судья честно возвращает такой
    # идентификатор неизвестным (в `blocks` лежит один ведущий на
    # ключ), а арбитраж отбрасывал его как посторонний — и решение,
    # ПРОТИВОРЕЧАЩЕЕ решению по ведущей находке, исчезало молча:
    # принятым оставалось первое, обе находки ключа закрывались,
    # гейт зеленел, цикл приходил к «успеху» — прямой контрпример
    # §1.5 контракта П0 («ни одно решение арбитра не принимается при
    # наличии противоречащего»). Поэтому посторонний — только тот, кого
    # НЕТ среди находок предъявленных споров (`lead_of`); всё
    # остальное поднимается на ведущего и гасит спор целиком.
    unresolved_by_lead: dict[str, list[str]] = {}
    for did, reason in unresolved_now.items():
        lead = lead_of.get(did)
        if lead is None:
            continue        # посторонний идентификатор — свой счёт
        unresolved_by_lead.setdefault(lead, []).append(
            reason if did in blocks else
            (f"решение названо по родичу [{did}] — спор судится по "
             f"ключу, ответ должен называть ведущую находку {lead}"))
    for lead, reason in empty_dossier.items():
        unresolved_by_lead.setdefault(lead, []).insert(0, reason)
    # A09/X-03: решение спора — решение КАЖДОЙ его находки. Дальше по
    # всему арбитражу — только эти два соответствия: они уже разнесены
    # с ключа на находки, и разных исходов у одного спора не бывает.
    unresolved_of = {f["id"]: "; ".join(
                         unresolved_by_lead[lead_of[f["id"]]])
                     for f in deadlocks
                     if lead_of[f["id"]] in unresolved_by_lead}
    # §1.5: при наличии противоречащего решения не принимается НИ
    # ОДНО — у неразрешённого спора решения нет нигде: ни в отчёте, ни
    # в исполнении (заплата, вопрос анкеты), ни в реестре.
    verdict_of = {f["id"]: verdicts[lead_of[f["id"]]]
                  for f in deadlocks
                  if lead_of[f["id"]] in verdicts
                  and f["id"] not in unresolved_of}

    # Исполнение «аудитор прав»: обработчик обязан дать патч. §12.8:
    # кроме тупиков, дозревших из терминальной отбраковки замком кода
    # — по ним законной заплаты нет, и арбитр не обходит замок
    # незаконной правкой: спор уходит владельцу вопросом анкеты, а
    # находка остаётся живой с названной причиной (arbiter_unenforced).
    # Запрет признаётся по ЛЮБОМУ носителю — полям реестра или файлам
    # отбраковки раундов (ревью A09, находка 1): писатель и судья
    # смотрят на одни и те же следы, иначе стёртое поле реестра
    # заставило бы арбитра велеть заплату, которой не существует.
    # Замок кода держится на МЕСТЕ правки, а не на записи реестра:
    # запрет по любой находке ключа — запрет по всему спору (A09/X-03).
    code_locked = {g["id"] for grp in groups
                   if any(code_locked_dispute(f, dossiers.get(f["id"]))
                          for f in grp)
                   for g in grp}
    # Заплата по спору ОДНА — её пишет представитель ключа; остальные
    # находки ключа получают тот же след исполнения.
    to_enforce = [grp[0] for grp in groups
                  if verdict_of.get(grp[0]["id"], {}).get("verdict")
                  == "аудитор прав" and grp[0]["id"] not in code_locked]
    # Исполненные вердикты «аудитор прав» — по ФАКТУ принятой заплаты
    # (аудит A3.5, 2026-09-04): прежде состояние ставилось по
    # вердикту, и отбракованная заплата навсегда закрывала находку.
    enforced_ids: list[str] = []
    patch_rejected: list[dict] = []
    new_doc = base_doc
    if to_enforce:
        if control:
            control()
        remarks = []
        for f in to_enforce:
            rm = dict(dossiers[f["id"]]["remark"] or {})
            rm["id"] = f["id"]
            remarks.append(rm)
        pack = {"round": 0, "remarks": remarks}
        resp = _respond_round(worker_llm, new_doc, pack, clause_by_key,
                              template=_PROMPT_ENFORCE)
        # Исполнение — строго в цели арбитража: патч, трогающий
        # строку вне цели своего тупика, отбраковывается ДО
        # применения (живой Лайт run-0040, 2026-08-23: обработчик
        # исполнил вердикт и заодно «поправил» чужую строку — дифф-
        # гейт краснел уже ПОСЛЕ применения, свод был испорчен).
        target_of = {}
        for f in to_enforce:
            rm0 = dossiers[f["id"]]["remark"] or {}
            target_of[f["id"]] = ((rm0.get("target") or {})
                                  .get("rule")) or "+"
        kept_answers = []
        for a in resp.get("answers", []):
            if not isinstance(a, dict):
                patch_rejected.append(
                    {"answer": repr(a)[:60],
                     "reasons": ["ответ обработчика не объект"]})
                continue
            if a.get("verdict") != "ПРИНЯТО":
                patch_rejected.append(
                    {"answer": a.get("remark"),
                     "reasons": ["арбитраж окончателен, а ответ не "
                                 "ПРИНЯТО — исполнение не засчитано"]})
                continue
            want = target_of.get(a.get("remark"))
            got_rid = (a.get("patch") or {}).get("rule_id")
            if want is not None and got_rid != want:
                patch_rejected.append(
                    {"answer": a.get("remark"),
                     "reasons": [f"исполнение вне цели арбитража: "
                                 f"патч трогает {got_rid!r}, цель "
                                 f"тупика — {want!r}"]})
                continue
            kept_answers.append(a)
        # Исполнение арбитража: «выбор чтения» здесь уже рассужен
        # арбитром («аудитор прав» = чтение однозначно) — в вопрос не
        # переводится; замок целостности посадки действует и тут.
        before = new_doc
        new_doc, accepted_targets, more_rejected, tokens = _apply_patches(
            new_doc, pack, {"answers": kept_answers}, 99,
            valid_anchors=set(clause_by_key),
            clause_texts=clause_by_key,
            convert_reading_choice=False)
        patch_rejected += more_rejected
        # Тупик исполнен, только если его ответ дошёл до применения,
        # не отбракован там, цель тупика — среди принятых целей заплат
        # И заплата оставила след в модели (строка-цель изменена, для
        # пропуска — появилась новая строка). Тупик без ответа
        # обработчика — отбраковка с причиной (fail-closed: молчание
        # не считается исполнением).
        answered = {a.get("remark") for a in kept_answers}
        rejected_ids = {r.get("answer") for r in patch_rejected}
        rows_before = {r["id"]: r for r in before.get("rules", [])}
        rows_after = {r["id"]: r for r in new_doc.get("rules", [])}
        rule_of_token = {t["id"]: t["rule"] for t in tokens}
        for f in to_enforce:
            fid = f["id"]
            if fid in rejected_ids:
                continue
            if fid not in answered:
                patch_rejected.append(
                    {"answer": fid,
                     "reasons": ["исполнение не получено: обработчик "
                                 "не дал ответа на замечание тупика"]})
            elif target_of[fid] not in accepted_targets:
                patch_rejected.append(
                    {"answer": fid,
                     "reasons": [f"ответ ПРИНЯТО без применённой "
                                 f"заплаты строки {target_of[fid]!r} "
                                 f"— исполнение не засчитано"]})
            elif not _enforcement_changed_row(
                    target_of[fid], rows_before, rows_after,
                    rule_of_token.get(f"T99-{fid}")):
                patch_rejected.append(
                    {"answer": fid,
                     "reasons": [f"заплата не меняет строку: "
                                 f"строка-цель {target_of[fid]!r} после "
                                 f"применения совпадает с прежней — "
                                 f"исполнение не засчитано"]})
            else:
                enforced_ids.append(fid)
    # Исполнение спора — исполнение ВСЕХ его находок: заплата одна, и
    # след её принятия несёт каждая находка ключа (A09/X-03).
    _enforced_leads = set(enforced_ids)
    enforced_ids = [g["id"] for grp in groups
                    if grp[0]["id"] in _enforced_leads for g in grp]

    # «В анкету»: вопрос части 2 с развилкой из двух чтений; строка
    # блокируется. Формулировки — из материалов спора, без модели.
    added_questions: list[str] = []
    question_reuse: dict[str, str] = {}
    # Тупик → id созданного вопроса: состояние «арбитр: в анкету»
    # ставится только тупику, чей вопрос действительно добавлен либо
    # переиспользован (question_reuse).
    question_of: dict[str, str] = {}
    for grp in groups:
        f = grp[0]
        v_now = verdict_of.get(f["id"], {}).get("verdict")
        # §12.8: «аудитор прав» по тупику, запрещённому замком кода,
        # исполняется НЕ заплатой, а передачей спора владельцу —
        # вопросом анкеты. Развилка там другая (не «чьё чтение
        # верно», а «менять ли требование кода»), поэтому и цель
        # вопроса своя: чужой вопрос-цель замечания её не заменит.
        unlawful = (v_now == "аудитор прав" and f["id"] in code_locked)
        if v_now != "в анкету" and not unlawful:
            continue
        d = dossiers[f["id"]]
        rm = d["remark"] or {}
        refs = rm.get("source_refs") or [{}]
        # Цель замечания — уже существующий вопрос анкеты (кодовый вопрос
        # GOAL / линии данных / истории либо вопрос части 2): развилка,
        # которую арбитр велит вынести в анкету, в анкете уже стоит — этим
        # самым вопросом. Исполнение = переиспользование цели; новый вопрос
        # без строки-носителя здесь не нужен (живой прогон H0-КИ-окна №3
        # 05.09: два тупика «выбор чтения» по Q-3a/3b-GOAL держали гейт
        # арбитража красным «без строки-носителя: вопрос не добавлен»).
        target_q = (rm.get("target") or {}).get("question")
        if target_q and not unlawful \
                and any(q.get("id") == target_q
                        for q in new_doc.get("questions", [])):
            question_reuse[f["id"]] = target_q
            continue
        target_rule = (rm.get("target") or {}).get("rule")
        qid = m.stable_question_id("2", f"арб-{f['id']}")
        rule_refs = [target_rule] if target_rule in rules_by_id else []
        if not rule_refs:
            # Пропуск без строки: вопрос привязывается к любой строке
            # той же клаузы либо остаётся без добавления — честно в
            # отчёт.
            same = [r["id"] for r in new_doc["rules"]
                    if any(ref.get("anchor") == refs[0].get("anchor")
                           for ref in r.get("sources", []))]
            rule_refs = same[:1]
        if not rule_refs:
            patch_rejected.append(
                {"answer": f["id"],
                 "reasons": [f"вердикт «{v_now}» без строки-носителя: "
                             f"вопрос не добавлен"]})
            continue
        # §12.8: у вопроса о запрете кода своя развилка — не «чьё
        # чтение источника верно», а «менять ли требование кода».
        # Решает владелец; ни свод, ни обработчик его не заменяют.
        code_words = (str(f.get("code_rejection") or "").strip()
                      or " | ".join(r for cr in d["code_rejections"]
                                    for r in cr["reasons"]))
        if unlawful:
            text = (f"Арбитр признал правоту аудитора, но заплату по "
                    f"этому месту запрещает замок кода. Замечание: "
                    f"{rm.get('text')} Запрет кода: {code_words} "
                    f"Как поступить?")
        else:
            text = (f"Аудит выявил спорное чтение источника. "
                    f"{rm.get('text')} Какое чтение верно?")
        norm = m.normalized_question_text(text)
        dup = next((q for q in new_doc["questions"]
                    if m.normalized_question_text(q.get("text", ""))
                    == norm), None)
        if dup is not None:
            # Смежные тупики рождают ОДИН и тот же вопрос (живой урок
            # UniA run-0051: инвариант дублей ронял арбитраж) —
            # вопрос один, строки-носители подцепляются к нему; след
            # переиспользования — в отчёте (question_reuse), гейт
            # судит по нему.
            for rid in rule_refs:
                if rid not in (dup.get("rule_refs") or []):
                    dup.setdefault("rule_refs", []).append(rid)
                rule = next(r for r in new_doc["rules"]
                            if r["id"] == rid)
                blockers = rule.setdefault("blockers", [])
                if dup["id"] not in blockers:
                    blockers.append(dup["id"])
            question_reuse[f["id"]] = dup["id"]
            continue
        if unlawful:
            title = (f"Запрет кода против замечания: "
                     f"{(rm.get('text') or '')[:60]}")
            options = [
                {"key": "а", "text": f"принять требование аудитора и "
                                     f"изменить требование кода: "
                                     f"{rm.get('proposal') or rm.get('text') or ''}"},
                {"key": "б", "text": f"оставить требование кода в "
                                     f"силе: {code_words}"},
            ]
        else:
            title = f"Спорное чтение: {(rm.get('text') or '')[:60]}"
            options = [
                {"key": "а", "text": f"чтение аудитора: "
                                     f"{rm.get('proposal') or rm.get('text') or ''}"},
                {"key": "б", "text": f"чтение обработчика: "
                                     f"{d['rejections'][-1] if d['rejections'] else 'текущая строка свода верна'}"},
            ]
        new_doc["questions"].append({
            "id": qid, "part": "2",
            "title": title,
            "text": text,
            "answer_format": {"type": "choice", "options": options},
            "rule_refs": rule_refs,
            # Якорь — от СТРОКИ-НОСИТЕЛЯ (валиден по построению);
            # аудиторский текст якоря бывает вымышленным ([табл.…] в
            # скобках — живой урок UniA run-0051: гейт извлечения
            # краснил трассировку вопросов арбитража).
            "source_refs": [dict(
                (next((r for r in new_doc["rules"]
                       if r["id"] == rule_refs[0]), {})
                 .get("sources")
                 or [{"sid": refs[0].get("sid"),
                      "anchor": refs[0].get("anchor")}])[0])],
        })
        for rid in rule_refs:
            rule = next(r for r in new_doc["rules"] if r["id"] == rid)
            blockers = rule.setdefault("blockers", [])
            if qid not in blockers:
                blockers.append(qid)
        added_questions.append(qid)
        question_of[f["id"]] = qid
    # Вопрос у спора ОДИН на все его находки (A09/X-03): прочие
    # находки ключа закрываются тем же вопросом — следом
    # переиспользования, а не вторым вопросом об одном и том же.
    for grp in groups:
        qid0 = question_of.get(grp[0]["id"]) \
            or question_reuse.get(grp[0]["id"])
        if not qid0:
            continue
        for g in grp[1:]:
            question_reuse.setdefault(g["id"], qid0)

    problems = m.validate_schema(new_doc) + m.validate_model(new_doc)
    if problems:
        raise ExchangeError("модель после арбитража не прошла контракт: "
                            + summarize_items(problems, limit=6, separator="; "))

    # Состояние реестра — по ФАКТУ исполнения вердикта, а не по
    # вердикту (аудит A3.5, 2026-09-04): «аудитор прав» закрывает
    # находку только принятой заплатой, «в анкету» — только созданным
    # (или переиспользованным) вопросом. Неисполненный вердикт
    # оставляет находку в состоянии «тупик» с названной причиной:
    # гейт арбитража краснеет, аудитору находка не запрещена, повторный
    # арбитраж судит её заново.
    reasons_by_id: dict[str, list[str]] = {}
    for r in patch_rejected:
        reasons_by_id.setdefault(str(r.get("answer")), []) \
            .extend(r.get("reasons") or [])
    unenforced: list[dict] = []
    for f in deadlocks:
        v = verdict_of.get(f["id"], {}).get("verdict")
        lead = lead_of[f["id"]]
        f.pop("arbiter_unenforced", None)
        f.pop("arbiter_unresolved", None)
        f.pop("arbiter_question", None)
        if f["state"] == "не разрешено арбитром":
            # Тупик судится в этом заходе заново: прежняя
            # неразрешённость не переживает новый суд.
            f["state"] = "тупик"
        # A09: решения по этому тупику неоднозначны (дубль, в том
        # числе одинаковый, или молчание арбитра) — спор НЕ разрешён:
        # состояние живое, причина названа словами, раунд его не
        # закрывает.
        if f["id"] in unresolved_of:
            f["state"] = "не разрешено арбитром"
            f["arbiter_unresolved"] = unresolved_of[f["id"]]
            continue
        if v == "обработчик прав":
            f["state"] = "арбитр: обработчик прав"
        elif v == "аудитор прав":
            if f["id"] in code_locked:
                # §12.8: аудитор прав, но заплату запрещает замок кода
                # — арбитр её не пишет. Находка остаётся ЖИВОЙ
                # («тупик») с названной причиной, а спор уходит
                # владельцу вопросом анкеты: без вопроса исполнения
                # нет и спор бы потерялся.
                qid = question_of.get(f["id"])
                reused = question_reuse.get(f["id"])
                asked = (qid is not None and qid in added_questions) \
                    or reused is not None
                reason = (
                    "вердикт «аудитор прав» исполнить заплатой нельзя: "
                    + (str(f.get("code_rejection") or "").strip()
                       or "замок кода запретил заплату")
                    + (f"; спор передан владельцу вопросом "
                       f"{qid or reused}" if asked else
                       "; вопрос владельцу НЕ поставлен: "
                       + ("; ".join(reasons_by_id.get(lead) or [])
                          or "строка-носитель не найдена")))
                f["arbiter_unenforced"] = reason
                if asked:
                    # Носитель id вопроса при самой находке: щит
                    # «ждёт ответа владельца» переживает границу
                    # мегакруга, где отчёта прежнего цикла уже нет.
                    f["arbiter_question"] = qid or reused
                unenforced.append({"deadlock": f["id"], "verdict": v,
                                   "reason": reason})
            elif f["id"] in enforced_ids:
                f["state"] = "арбитр: аудитор прав"
            else:
                reason = ("вердикт «аудитор прав» не исполнен: "
                          + ("; ".join(reasons_by_id.get(lead) or [])
                             or "заплата не принята"))
                f["arbiter_unenforced"] = reason
                unenforced.append({"deadlock": f["id"], "verdict": v,
                                   "reason": reason})
        elif v == "в анкету":
            qid = question_of.get(f["id"])
            reused = question_reuse.get(f["id"])
            if (qid is not None and qid in added_questions) \
                    or reused is not None:
                f["state"] = "арбитр: в анкету"
            else:
                reason = ("вердикт «в анкету» не исполнен: "
                          + ("; ".join(reasons_by_id.get(lead) or [])
                             or "вопрос анкеты не создан"))
                f["arbiter_unenforced"] = reason
                unenforced.append({"deadlock": f["id"], "verdict": v,
                                   "reason": reason})

    _dump_registry(exchange_dir / "registry.json", registry)
    # Переигровка без тупиков не разрушает исполненное: при пустом
    # списке тупиков new_doc = базовая доарбитражная модель, и
    # безусловная запись затирала бы версии с уже исполненными
    # вердиктами (живой Лайт run-0040, 2026-08-23).
    if deadlocks or not (exchange_dir / "versions"
                         / "model-arbiter.json").is_file():
        _dump(exchange_dir / "versions" / "model-arbiter.json",
              new_doc)
        (exchange_dir / "versions" / "svod-arbiter.md").write_text(
            render.render_svod(new_doc), encoding="utf-8")
        (exchange_dir / "versions" / "anketa-arbiter.md").write_text(
            render.render_anketa(new_doc), encoding="utf-8")
    # Частичная переарбитрация (возврат отдельного тупика) СЛИВАЕТСЯ с
    # прежним отчётом: вердикт на каждый тупик цикла всегда один и
    # последний (живой случай пилотной линии 2026-08-18 — фокусный
    # повтор R1-A1-092
    # перезаписал отчёт целиком, и гейт честно покраснел).
    merged: dict[str, dict] = {}
    for v in prev_report.get("verdicts", []):
        if v.get("deadlock"):
            merged[v["deadlock"]] = v
    prev_enforced = [str(i) for i in
                     prev_report.get("enforced_deadlocks") or []]
    for f in deadlocks:
        # A09: у неразрешённого спора решения нет — в перечень решений
        # он не попадает (и прежнее решение оттуда снимается), его
        # место — перечень unresolved.
        if f["id"] in unresolved_of:
            merged.pop(f["id"], None)
            continue
        merged[f["id"]] = {
            "deadlock": f["id"],
            "verdict": verdict_of.get(f["id"], {}).get("verdict"),
            "basis": verdict_of.get(f["id"], {}).get("basis")}
    # Спор, ждущий ответа владельца, исход в этом отчёте имеет СВОЙ
    # (`awaiting_owner`): решение прежнего захода осталось историей
    # того отчёта, но вторым исходом того же спора здесь быть не может
    # — исход у спора один (§1.3).
    for a in awaiting:
        merged.pop(a["deadlock"], None)
    # След исполнения тупиков прежних частичных арбитражей сохраняется
    # в отчёте (вердикт на тупик один и последний — так же и след его
    # исполнения): исполненные тупики, добавленные и переиспользованные
    # вопросы, неисполненные вердикты; переарбитрированные в этом
    # заходе — только по факту этого захода. Модель-база несёт те же
    # строки и вопросы (см. base_doc выше) — отчёт, реестр и модель
    # согласны.
    current = {f["id"] for f in deadlocks}
    current_q = {m.stable_question_id("2", f"арб-{i}") for i in current}
    enforced_deadlocks = [i for i in prev_enforced
                          if i not in current] + enforced_ids
    added_questions = [q for q in prev_report.get("added_questions") or []
                       if q not in current_q] + added_questions
    question_reuse = {**{k: v for k, v in
                         (prev_report.get("question_reuse") or {}).items()
                         if k not in current},
                      **question_reuse}
    unenforced = [u for u in prev_report.get("unenforced") or []
                  if u.get("deadlock") not in current] + unenforced
    # A09: перечень неразрешённого — тупики этого захода в порядке
    # списка тупиков, затем лишние (неизвестные) идентификаторы ответа
    # арбитра по алфавиту. Из прежнего отчёта переносится запись ТОЛЬКО
    # о споре, который (а) решения в этом отчёте не имеет и (б) числится
    # неразрешённым в реестре (ревью A09 №2, находка 1). Прежде
    # переносилось всё, что не судилось этим заходом: лишнее упоминание
    # арбитром уже РЕШЁННОГО тупика цикла (не предъявлявшегося!)
    # рождало запись, которую ни один честный заход не снимал — тупик
    # больше не «тупик», в разбирательства не попадает, — и гейт был
    # красным вечно, а счётчик считал два спора за три.
    listed_ids = {d.get("id") for d in listed}
    unresolved_list = [
        {"deadlock": u.get("deadlock"), "reason": u.get("reason")}
        for u in prev_report.get("unresolved") or []
        if u.get("deadlock") not in current
        and u.get("deadlock") in listed_ids
        and u.get("deadlock") not in merged
        and (entry_of.get(u.get("deadlock")) or {}).get("state")
        == "не разрешено арбитром"]
    unresolved_list += [{"deadlock": f["id"],
                         "reason": unresolved_of[f["id"]]}
                        for f in deadlocks if f["id"] in unresolved_of]
    # Посторонний — тот, кого нет среди находок предъявленных споров
    # (`lead_of`, а не просто «не судился этим заходом»): упоминание
    # РОДИЧА уже поднято на ведущего выше и гасит спор целиком —
    # второй записью о том же оно здесь не становится (К-1).
    unresolved_list += [{"deadlock": did, "reason": reason}
                        for did, reason in sorted(unresolved_now.items())
                        if did not in lead_of]
    order = [f["id"] for f in verdict_summary.get("deadlocks", [])]
    verdict_list = [merged[i] for i in order if i in merged] + \
        [merged[i] for i in sorted(merged) if i not in order]
    # Считается РАССМОТРЕННОЕ, а не всё написанное в перечнях (ревью
    # A09, находка 6): «Тупиков рассмотрено» — число РАЗНЫХ споров
    # ЭТОГО цикла, у которых есть исход: решение, запись «не
    # разрешено» либо ожидание ответа владельца. Сумма длин перечней
    # считала один и тот же тупик дважды, попади он сразу в два
    # (лишнее упоминание уже решённого спора — «тупиков 3» при двух).
    # Посторонний идентификатор ответа арбитра и запись без формы
    # («запись #N …») спорами цикла не являются: они не исчезают — их
    # считает свой счётчик и показывает свой перечень, а гейт по ним
    # краснеет.
    foreign_unresolved = [u for u in unresolved_list
                          if u["deadlock"] not in listed_ids]
    outcome_ids = {v.get("deadlock") for v in verdict_list} \
        | {u.get("deadlock") for u in unresolved_list} \
        | {a["deadlock"] for a in awaiting}
    report = {
        "deadlocks": len(outcome_ids & listed_ids),
        # Лишние идентификаторы ответа арбитра — отдельным счётом.
        "unresolved_foreign": len(foreign_unresolved),
        "verdicts": verdict_list,
        "by_verdict": {v: sum(1 for e in verdict_list
                              if e.get("verdict") == v)
                       for v in ARBITER_VERDICTS},
        # Счётчик исполнений — по ФАКТУ принятых заплат, не по числу
        # ответов обработчика (аудит A3.5).
        "enforced": len(enforced_deadlocks),
        "enforced_deadlocks": enforced_deadlocks,
        "unenforced": unenforced,
        # A09: споры без однозначного решения арбитра — с причиной
        # словами; гейт требует по каждому тупику ЛИБО одно решение,
        # ЛИБО запись здесь.
        "unresolved": unresolved_list,
        # §12.8 + ревью A09 №2, находка 3: споры, переданные владельцу
        # вопросом анкеты и ждущие его ответа. Третий законный исход:
        # арбитру они в этом заходе не предъявлялись, решения не имеют
        # и остаются живыми — «успех» цикла невозможен.
        "awaiting_owner": awaiting,
        "added_questions": added_questions,
        "question_reuse": question_reuse,
        "patch_rejections": patch_rejected,
        "final_version": "model-arbiter.json",
    }
    _dump(exchange_dir / "arbiter.json", report)
    return report


def main(argv: list[str] | None = None, auditor_override=None,
         worker_override=None) -> int:
    import sys
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")   # У-14: печать кириллицы
    import argparse
    from cdpm import llm as llm_mod
    ap = argparse.ArgumentParser(
        description="Аудит-цикл CDPM: обработчик — аудитор")
    ap.add_argument("kit", help="каталог комплекта заморозки")
    ap.add_argument("extract_dir", help="каталог результата извлечения")
    ap.add_argument("--out-dir", required=True)
    ap.add_argument("--auditor", default="cloud",
                    choices=["local", "cloud", "auto"],
                    help="канал модели-аудитора")
    ap.add_argument("--worker", default="cloud",
                    choices=["local", "cloud", "auto"],
                    help="канал модели-обработчика")
    ap.add_argument("--scope", default="any",
                    choices=["any", "local-only"])
    ap.add_argument("--max-rounds", type=int, default=5)
    args = ap.parse_args(argv)
    auditor = auditor_override or llm_mod.cosmos_llm(
        args.scope, requested=args.auditor)
    worker = worker_override or llm_mod.cosmos_llm(
        args.scope, requested=args.worker)
    try:
        s = run_exchange(Path(args.kit), Path(args.extract_dir),
                         Path(args.out_dir), auditor, worker,
                         args.max_rounds)
    except (ExchangeError, Exception) as e:                # noqa: BLE001
        print(f"ОТКАЗ: {e}")
        return 1
    hist = "; ".join(f"обмен {h['round']}: (Б,К,С)={tuple(h['weighty'])}"
                     for h in s["history"])
    print(f"вердикт: {s['verdict']} за {s['rounds']} обменов; {hist}; "
          f"тупиков {len(s['deadlocks'])}")
    print(f"итоговая версия: "
          f"{(Path(args.out_dir) / 'versions' / s['final_version']).resolve()}")
    print(f"вердикт цикла: "
          f"{(Path(args.out_dir) / 'verdict.json').resolve()}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
